
    /* Alinur — কাস্টম বাংলা ফন্ট, অ্যাপ টাইটেলে ব্যবহারের জন্য */
    @font-face{font-display:swap;font-family:'Alinur';src:url(data:font/ttf;base64,) format('truetype');}

    /* CSS ভেরিয়েবল — DARK WOOD THEME
    */
    :root {
      --ink:    #1a0f06;
      --gold:   var(--gold);
      --gold2:  #e0b84a;
      --gold3:  #f5d06e;
      --muted:  #8a7a60;
      --border: #c8a860;

      /* ---- --dz-* design tokens ----
         Promoted here from body{} (further down this file) so they're
         available app-wide, not just after body renders. Values are
         identical to the original body{} block — this is a relocation,
         not a change. The body{} declaration below is left in place
         (redeclaring the same values is harmless) to avoid touching
         code proven to work; this :root copy just makes the tokens
         reliably available to earlier-loading rules too. */
      --dz-primary:        #cc785c;
      --dz-primary-active: #a9583e;
      --dz-primary-soft:   #f3e3dc;
      --dz-ink:            #141413;
      --dz-body:           #3d3d3a;
      --dz-body-strong:    #252523;
      --dz-muted:          #6c6a64;
      --dz-muted-soft:     #8e8b82;
      --dz-hairline:       #e6dfd8;
      --dz-hairline-soft:  #ebe6df;
      --dz-canvas:         #faf9f5;
      --dz-surface-soft:   #f5f0e8;
      --dz-surface-card:   #efe9de;
      --dz-surface-strong: #e8e0d2;
      --dz-success:        #5db872;
      --dz-error:          #c64545;
      --dz-serif: 'Noto Serif Bengali', 'Copernicus', 'Tiempos Headline', serif;

      /* ---- --fab-* design tokens ----
         Previously only defined inside #fabricOverlay (scoped there).
         Promoted to :root, unscoped, so other files needing the same
         fabric-overlay palette (button-theme.css, card-theme.css) can
         reference them without duplicating hex. Values unchanged. */
      --fab-canvas:              var(--dz-canvas);
      --fab-surface-card:        var(--dz-surface-card);
      --fab-surface-strong:      var(--dz-surface-strong);
      --fab-surface-dark:        #181715;
      --fab-surface-dark-elev:   #252320;
      --fab-ink:                 var(--dz-ink);
      --fab-body:                var(--dz-body);
      --fab-muted:               var(--dz-muted);
      --fab-muted-soft:          var(--dz-muted-soft);
      --fab-hairline:            var(--dz-hairline);
      --fab-coral:               var(--dz-primary);
      --fab-coral-active:        var(--dz-primary-active);
      --fab-teal:  #5db8a6;
      --fab-amber: #e8a55a;
      --fab-serif: 'Noto Serif Bengali', Georgia, 'Tiempos Headline', 'EB Garamond', serif;
      --fab-sans:  'Noto Sans Bengali', -apple-system, 'StyreneB', 'Inter', sans-serif;
      --fab-mono:  'JetBrains Mono', 'IBM Plex Mono', ui-monospace, monospace;

      /* Shared utility values */
      --wood-grain-fine: repeating-linear-gradient(
        90deg,
        transparent 0px, transparent 5px,
        rgba(255,210,120,0.045) 5px, rgba(255,210,120,0.045) 6px,
        transparent 6px, transparent 11px,
        rgba(0,0,0,0.10) 11px, rgba(0,0,0,0.10) 12px,
        transparent 12px, transparent 18px,
        rgba(255,200,100,0.030) 18px, rgba(255,200,100,0.030) 19px,
        transparent 19px, transparent 25px,
        rgba(0,0,0,0.07) 25px, rgba(0,0,0,0.07) 26px,
        transparent 26px, transparent 34px
      );
      --wood-grain-wide: repeating-linear-gradient(
        90deg,
        rgba(255,215,110,0.022) 0px, rgba(255,215,110,0.022) 55px,
        rgba(0,0,0,0.055) 55px, rgba(0,0,0,0.055) 110px,
        rgba(255,210,100,0.018) 110px, rgba(255,210,100,0.018) 165px,
        rgba(0,0,0,0.060) 165px, rgba(0,0,0,0.060) 220px
      );
      --wood-grain-pore: repeating-linear-gradient(
        87deg,
        transparent, transparent 40px,
        rgba(0,0,0,0.04) 41px, rgba(0,0,0,0.04) 42px,
        transparent 42px, transparent 85px,
        rgba(255,185,70,0.018) 86px, rgba(255,185,70,0.018) 87px
      );
      --wood-base: linear-gradient(180deg,
        #6b3e18 0%, #5a3210 18%, #4e2c0e 40%, #56300f 65%, #4a2a0c 100%
      );
    }

    /* RESET + BASE
    */
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      font-family: var(--fab-sans);
      color: var(--dz-ink);
      min-height: 100vh;
      position: relative;
      overflow-x: hidden;
      isolation: isolate;
      background-color: var(--dz-canvas);
      background-image: none;
    }

    /* HEADER — Dark Teal / Deep Cyan
    */
    .hdr {
      background: transparent;
      color: var(--dw-white);
      position: sticky;
      top: 0;
      z-index: var(--z-popover);
      contain: layout style paint;
      box-shadow: none;
      border-bottom: none;
      padding-bottom: 28px;
    }
    /* হোম ট্যাবে ক্যালেন্ডার কার্ডের নিচে বাড়তি ফাঁকা জায়গা কমানো — কার্ডগুলো উপরে তুলতে */
    body.show-home .hdr {
      padding-bottom: 6px;
    }
    .hdr-brand,
    .hdr-right {
      background-color: transparent;
      background-image: none;
    }
    /* app-title */
    .app-title {
      background: none;
      background-image: none;
      -webkit-background-clip: unset;
      background-clip: unset;
      -webkit-text-fill-color: var(--dw-white-full);
      color: var(--dw-white-full);
      animation: none;
      filter: none;
    }
    /* app-sub */
    .app-sub {
      color: rgba(255,255,255,0.70);
      -webkit-text-fill-color: rgba(255,255,255,0.70);
      text-shadow: none;
    }

    /* ক্যালেন্ডার কার্ড: সবসময় সাদা/নীল ফিক্সড ডিজাইন — তাই কোনো ওভাররাইড নেই */

    /* notification + menu icon */
    .hdr svg path,
    .hdr svg circle,
    .hdr svg line,
    .hdr svg polyline { stroke: var(--dw-white); }
    .hdr .menu-bar    { background-color: var(--dw-white); }
    .hdr .notif-btn svg path { stroke: var(--dw-white) !important; }

    .hdr-topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      position: relative;
      background:
        radial-gradient(ellipse at 85% 0%, rgba(255,255,255,0.06) 0%, transparent 55%),
        var(--gradient-header-teal);
      border-radius: 0 0 22px 22px;
      padding: calc(14px + env(safe-area-inset-top, 0px)) 14px 50px;
      margin-bottom: -40px;
      border-bottom: none;
    }
    .hdr-brand {
      display: flex;
      align-items: flex-start;
      gap: 0;
      flex: 1;
      min-width: 0;
    }
    @keyframes ribbonShimmer {
      0%   { background-position: 160% 0, 0 0; }
      100% { background-position: -60% 0, 0 0; }
    }
    .hdr-ribbon {
      position: absolute;
      top: 0;
      left: 16px;
      width: 26px;
      height: 58px;
      background:
        linear-gradient(
          108deg,
          transparent 42%,
          rgba(255,255,255,0.08) 48%,
          rgba(255,255,255,0.14) 50%,
          rgba(255,255,255,0.08) 52%,
          transparent 58%
        ) no-repeat,
        var(--gradient-header-accent);
      background-size: 250% 100%, 100% 100%;
      clip-path: polygon(0 0, 100% 0, 100% 100%, 50% 78%, 0 100%);
      box-shadow: 0 2px 6px rgba(0,0,0,0.35);
      z-index: var(--z-local);
      pointer-events: none;
      animation: ribbonShimmer 4s linear infinite;
    }

    @font-face{font-display:swap;font-family:'Mah';src:url(data:font/ttf;base64,) format('truetype');}

    @keyframes titleShimmer {
      0%   { background-position: -150% 0, 0 0; }
      100% { background-position: 250% 0, 0 0; }
    }

    .app-title {
      font-family: 'Mah', 'Alinur', 'Noto Serif Bengali', 'Copernicus', 'Tiempos Headline', serif;
      font-size: 27px;
      font-weight: 600;
      letter-spacing: -0.2px;
      color: var(--dw-white-full);
      line-height: 1.2;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      text-transform: none;
      position: relative;
    }
    .app-sub {
      font-size: 12px; color: rgba(255,255,255,0.65); letter-spacing: 0.2px;
      margin-top: 2px; font-weight: 500; text-transform: none;
    }
    .hdr-right {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-shrink: 0;
    }

    /* KPI স্ট্যাট কার্ড স্ট্রিপ */
    .kpi-strip {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 8px;
      padding: 4px 10px 0;
      margin-bottom: 10px;
      position: relative;
      z-index: var(--z-raised);
    }
    .kpi-strip.kpi-strip-3 {
      grid-template-columns: repeat(3, 1fr);
    }
    .kpi-strip > * {
      min-width: 0;
      max-width: 100%;
    }
    .kpi-strip .home-card.kpi-mini-card {
      margin: 0;
    }
    .kpi-strip .home-card.kpi-mini-card .card-body {
      padding: 16px 10px 18px;
      min-height: 118px;
    }
    .kpi-strip .home-card.kpi-mini-card .icon-medallion,
    .kpi-strip .home-card.kpi-mini-card .icon-inner {
      width: 32px !important; height: 32px !important;
      font-size: 14px !important;
    }
    .kpi-strip .home-card.kpi-mini-card .card-title {
      font-size: 12px !important;
    }
    .kpi-strip-3 .home-card.card-c5.kpi-mini-card .card-title,
    body .kpi-strip-3 .home-card.card-c5.kpi-mini-card .card-title {
      text-align: left;
      align-self: flex-start;
      font-family: var(--fab-sans) !important;
      font-size: 11px !important;
      font-weight: 600 !important;
      letter-spacing: 0.01em;
      line-height: 1.35;
      background: none !important;
      -webkit-background-clip: initial !important;
      -webkit-text-fill-color: var(--dz-muted) !important;
      background-clip: initial !important;
      filter: none !important;
      color: var(--dz-muted) !important;
    }
    .kpi-strip-3 .home-card.card-c5.kpi-mini-card .card-body {
      padding: 16px 12px 16px;
      gap: 6px;
      align-items: flex-start;
      justify-content: center;
      height: 100%;
    }
    .kpi-strip .home-card.kpi-mini-card .card-count {
      font-size: var(--font-xs) !important;
    }
    .kpi-strip .home-card.kpi-mini-card .card-count#kpiNetCashStrip {
      font-family: var(--fab-sans) !important;
      font-size: clamp(12px, 15px, 19px) !important;
      font-weight: 800 !important;
      line-height: 1.2;
      letter-spacing: -0.01em;
      color: var(--dz-ink);
      white-space: nowrap;
      overflow: visible;
      text-overflow: clip;
      max-width: 100%;
      display: block;
    }
    .kpi-strip .home-card.kpi-mini-card .card-count#kpiNetCashStrip.is-profit {
      color: var(--dz-success) !important;
    }
    .kpi-strip .home-card.kpi-mini-card .card-count#kpiNetCashStrip.is-loss {
      color: var(--dw-loss-red-alt) !important;
    }
    .kpi-mini-card {
      background: var(--dz-canvas);
      border: 1px solid var(--dz-hairline);
      border-radius: var(--radius-3xl);
      padding: 12px 10px 14px;
      box-shadow: 0 1px 3px rgba(20,20,19,0.06);
      display: flex;
      flex-direction: column;
      gap: 6px;
      position: relative;
      overflow: hidden;
      transition: box-shadow var(--dur-fast) ease, transform var(--dur-fast) ease;
    }
    .kpi-mini-card:active {
      transform: scale(0.98);
    }
    /* Aggregate Report কার্ড — coral-accented, একটু আলাদা করে ফিচার্ড লুক */
    .kpi-strip .home-card.card-c5.kpi-mini-card {
      background: var(--dz-primary-soft);
      border: 1px solid rgba(204,120,92,0.35);
    }
    .kpi-strip .home-card.card-c5.kpi-mini-card .card-title {
      color: var(--dz-primary-active) !important;
      -webkit-text-fill-color: var(--dz-primary-active) !important;
    }
    .kpi-strip .home-card.card-c5.kpi-mini-card .icon-inner {
      background: var(--dz-canvas) !important;
      color: var(--dz-primary-active) !important;
      border-radius: var(--radius-lg) !important;
      box-shadow: none !important;
    }
    /* নোটিফিকেশন বাটন — বক্সবিহীন, ক্যালেন্ডার খোদাই স্টাইল */
    .notif-btn {
      background: none;
      border: none;
      cursor: pointer;
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
      position: relative;
      padding: 5px 0 5px 5px;
      transition: transform var(--dur-base);
    }
    .notif-btn:hover { transform: scale(1.12); }
    .notif-badge {
      position: absolute; top: 3px; right: -1px;
      width: 9px; height: 9px; border-radius: var(--radius-circle);
      background: var(--dw-danger-bright);
      border: 1.5px solid var(--dw-border-dark);
      display: none;
    }
    .notif-badge.show { display: block; }

    /* নোটিফিকেশন প্যানেল */
    .notif-overlay {
      display: none; position: fixed; inset: 0;
      z-index: var(--z-toast-mid);
    }
    .notif-overlay.open { display: block; }
    .notif-panel {
      position: absolute; top: 70px; right: 12px;
      width: min(320px, calc(100vw - 24px));
      border-radius: var(--radius-4xl);
      border: 1.5px solid var(--border);
      overflow: hidden;
      box-shadow: 0 8px 32px rgba(0,0,0,.45);
    }
    .notif-head {
      display: flex; align-items: center; justify-content: space-between;
      padding: 11px 14px 9px;
      border-bottom: 1px solid rgba(200,168,96,.2);
    }
    .notif-head-title { font-size: 12px; font-weight: 800; color: var(--gold2); }
    .notif-clear-btn {
      font-size: var(--font-xs); color: var(--muted); -webkit-text-fill-color: var(--muted);
      background: none; border: none; cursor: pointer;
      font-family: var(--fab-sans);
    }
    .notif-list {
      max-height: 320px; overflow-y: auto;
    }
    .notif-empty {
      padding: 22px 14px; text-align: center;
      font-size: 11px; color: var(--muted);
    }
    .notif-item {
      display: flex; align-items: flex-start; gap: 10px;
      padding: 10px 14px;
      border-bottom: 1px solid rgba(200,168,96,.1);
      animation: notifIn .25s ease;
    }
    @keyframes notifIn { from { opacity:0; transform:translateY(-6px) } to { opacity:1; transform:none } }
    .notif-icon {
      width: 30px; height: 30px; border-radius: var(--radius-circle);
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0; font-size: 14px;
    }
    .notif-icon.success { background: rgba(78,203,122,.15); }
    .notif-icon.error   { background: rgba(224,80,80,.15); }
    .notif-icon.info    { background: rgba(100,160,224,.15); }
    .notif-text { flex: 1; min-width: 0; }
    .notif-msg  { font-size: 11px; color: var(--gold3); line-height: 1.4; }
    .notif-time { font-size: var(--font-2xs); color: var(--muted); margin-top: 2px; }

    /* হ্যামবার্গার মেনু বাটন */
    .menu-btn {
      width: 38px; height: 38px;
      background: none;
      border: none;
      border-radius: var(--radius-lg);
      cursor: pointer;
      display: flex; flex-direction: column;
      align-items: center; justify-content: center;
      gap: 5px;
      transition: transform var(--dur-base);
      flex-shrink: 0;
      padding: 0;
    }
    .menu-btn:hover { transform: scale(1.12); }
    .menu-bar {
      display: block;
      width: 19px; height: 2.5px;
      background: var(--dw-bg-deepest);
      border-radius: var(--radius-xs);
    }

    /* ক্যালেন্ডার কার্ড — DESIGN.md cream/coral/hairline স্টাইল */
    .cal-card {
      background: var(--dz-canvas);
      border: 1px solid var(--dz-hairline);
      border-radius: var(--radius-3xl);
      margin: 5px 10px 6px;
      box-shadow: none;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }
    /* হোম স্ক্রিনে ক্যালেন্ডার কার্ডের ব্যাকগ্রাউন্ড স্ক্রিন-র‍্যাপের কালারের সাথে মেলানো */
    body.show-home #dashCalCard {
      background: var(--bg, #f5f0eb);
      outline: 1px solid rgba(200,150,30,0.55);
      outline-offset: 1px;
    }
    body:not(.show-home) #dashCalCard {
      display: none !important;
    }
    .cal-top {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      gap: 8px;
      padding: 8px 14px 6px;
      flex-wrap: wrap;
      flex-shrink: 0;
    }
    .agg-full-card .cal-top {
      padding: 8px 14px 4px;
    }
    .cal-dates {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .cal-sep {
      color: var(--dz-hairline);
      font-size: 13px;
      font-weight: 300;
    }
    .cal-date-btn {
      font-family: var(--fab-sans);
      background: none;
      border: none;
      padding: 0;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 5px;
      font-size: 13px;
      font-weight: 500;
      color: var(--dz-muted);
      -webkit-text-fill-color: var(--dz-muted);
      line-height: 1.4;
    }
    .cal-date-btn svg { color: var(--dz-muted-soft); flex-shrink: 0; }

    /* Aggregate Report কার্ড (ক্যালেন্ডার কার্ডের জায়গায়, একই সাইজে) */
    .agg-full-card {
      cursor: pointer;
      transition: box-shadow var(--dur-sm);
    }
    .agg-full-card:active {
      box-shadow: 0 1px 3px rgba(20,20,19,0.10);
    }
    .agg-full-card-body {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 8px;
      padding: 4px 14px 10px;
      flex: 1;
    }
    .agg-full-stat {
      display: flex;
      flex-direction: column;
      gap: 2px;
      background: var(--dz-surface-card);
      border-radius: var(--radius-2xl);
      padding: 7px 12px;
    }
    .agg-full-stat-label {
      font-family: var(--fab-sans);
      font-size: 11px;
      font-weight: 600;
      color: var(--dz-muted);
    }
    .agg-full-stat-val {
      font-family: var(--fab-sans);
      font-size: 15px;
      font-weight: 800;
      color: var(--dz-ink);
      letter-spacing: -0.01em;
    }
    .agg-full-stat-val.is-loss { color: var(--dw-loss-red-alt); }

    /* সাপ্তাহিক দিন স্ট্রিপ */
    .hdr-week-cal {
      display: flex;
      gap: 4px;
      padding: 0 8px 8px;
      border-top: 1px solid var(--dz-hairline-soft);
      padding-top: 6px;
      flex: 1;
    }
    .hwc-day {
      flex: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 4px;
      padding: 5px 2px;
      border-radius: var(--radius-2xl);
      border: 1.5px solid transparent;
      transition: background var(--dur-md), border-color var(--dur-md);
    }
    .hwc-day.hwc-today {
      border-color: var(--dz-primary);
      background: var(--dz-primary-soft);
    }
    .hwc-name {
      font-size: 12px;
      font-weight: 500;
      color: var(--dz-muted-soft);
      line-height: 1.1;
      white-space: nowrap;
      letter-spacing: 0;
    }
    .hwc-date {
      font-size: 17px;
      font-weight: 700;
      color: var(--dz-ink);
      line-height: 1.1;
      letter-spacing: 0;
    }
    .hwc-day.hwc-today .hwc-name,
    .hwc-day.hwc-today .hwc-date {
      color: var(--dz-primary-active);
    }

    /* Fund Flow Overview কার্ড — DESIGN.md cream/coral স্টাইল */
    .fundflow-card {
      transition: box-shadow var(--dur-sm);
      display: flex;
      flex-direction: column;
      /* কার্ডের সাইজ কনটেন্টের সাথে ফিট — কোনো অতিরিক্ত/ফাঁকা জায়গা থাকবে না,
         আবার ভেতরে নতুন কিছু যোগ হলে কার্ড অপ্রয়োজনীয়ভাবে বড়ও হবে না */
      height: auto;
      max-height: 270px;
      overflow: hidden;
    }
    /* কার্ড বড় হলে ভেতরের কন্টেন্ট অতিরিক্ত জায়গা সঠিকভাবে নেবে */
    #ffh-empty { flex: 1; }
    .ffh-data {
      display: flex;
      flex-direction: column;
      min-height: 0;      /* flex child কে scroll করতে দিতে জরুরি */
      overflow-y: auto;   /* কন্টেন্ট max-height-এর চেয়ে বেশি হলে ভেতরেই স্ক্রল হবে */
    }
    .ffh-data > div:first-child { flex-shrink: 0; }

    /* MAIN + HOME GRID
    */
    .main {
      padding: 14px 12px 40px;
      width: 100%;
    }
    .home-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      grid-auto-rows: 1fr;
      gap: 8px;
    }

    /* HOME CARD — 3D Wooden Panel
    */
    .home-card {
      border-radius: var(--radius-3xl);
      overflow: hidden;
      position: relative;
      cursor: pointer;
      transition: transform var(--dur-sm);
      min-height: 100px;
      /* Brass inlay double border */
      outline: 1px solid rgba(200,150,30,0.55);
      outline-offset: 1px;
      contain: layout style;
    }
    .home-card:active { transform: scale(.97); }

    /* Bevelled top-left highlight — the "3D raised panel" illusion */
    .home-card::before {
      content: '';
      position: absolute;
      inset: 0;
      border-radius: var(--radius-3xl);
      background:
        /* Top-left bevel highlight */
        linear-gradient(135deg,
          rgba(255,220,120,0.16) 0%,
          rgba(255,220,120,0.05) 18%,
          transparent 40%
        ),
        /* Bottom-right shadow — panel depth */
        linear-gradient(315deg,
          rgba(0,0,0,0.45) 0%,
          rgba(0,0,0,0.15) 20%,
          transparent 45%
        ),
        /* VERTICAL wood grain overlay on card face */
        repeating-linear-gradient(
          90deg,
          transparent 0px, transparent 5px,
          rgba(255,200,80,0.038) 5px, rgba(255,200,80,0.038) 6px,
          transparent 6px, transparent 11px,
          rgba(0,0,0,0.09) 11px, rgba(0,0,0,0.09) 12px,
          transparent 12px, transparent 18px,
          rgba(255,210,90,0.025) 18px, rgba(255,210,90,0.025) 19px,
          transparent 19px, transparent 26px
        );
      pointer-events: none;
      z-index: 0;
    }

    /* Card 1: রেগুলার কাস্টমার — Walnut (brighter) */
    .home-card.card-c1 {
      background:
        radial-gradient(ellipse at 30% 15%, rgba(240,180,80,0.28) 0%, transparent 55%),
        var(--mat-walnut);
      border: 2px solid rgba(210,150,40,0.80);
      box-shadow:
        6px 6px 20px rgba(0,0,0,0.85),
        -1px -1px 4px rgba(240,190,70,0.18),
        2px 2px 0 rgba(255,220,110,0.12) inset,
        -2px -2px 0 rgba(0,0,0,0.50) inset,
        0 -4px 12px rgba(0,0,0,0.35) inset;
    }
    .home-card.card-c1:hover {
      transform: translateY(-2px);
      box-shadow:
        8px 10px 28px rgba(0,0,0,0.90),
        0 0 18px rgba(210,150,40,0.30),
        -1px -1px 4px rgba(240,190,70,0.18),
        2px 2px 0 rgba(255,220,110,0.14) inset,
        -2px -2px 0 rgba(0,0,0,0.50) inset;
    }

    /* Card 2: ইর-রেগুলার কাস্টমার — Ebony */
    .home-card.card-c2 {
      background:
        radial-gradient(ellipse at 60% 15%, rgba(120,160,200,0.14) 0%, transparent 50%),
        var(--mat-ebony);
      border: 2px solid rgba(100,140,180,0.60);
      box-shadow:
        6px 6px 20px rgba(0,0,0,0.85),
        -1px -1px 4px rgba(140,180,220,0.08),
        2px 2px 0 rgba(180,210,240,0.08) inset,
        -2px -2px 0 rgba(0,0,0,0.60) inset,
        0 -4px 12px rgba(0,0,0,0.45) inset;
    }
    .home-card.card-c2:hover {
      transform: translateY(-2px);
      box-shadow:
        8px 10px 28px rgba(0,0,0,0.90),
        0 0 18px rgba(80,130,180,0.20),
        -1px -1px 4px rgba(140,180,220,0.08),
        2px 2px 0 rgba(180,210,240,0.10) inset,
        -2px -2px 0 rgba(0,0,0,0.60) inset;
    }

    /* Card 3: রেগুলার মহাজন — Teak/Brass */
    .home-card.card-c3 {
      background:
        radial-gradient(ellipse at 40% 15%, rgba(240,200,60,0.22) 0%, transparent 50%),
        var(--mat-teak-brass);
      border: 2px solid rgba(210,180,40,0.75);
      box-shadow:
        6px 6px 20px rgba(0,0,0,0.85),
        -1px -1px 4px rgba(240,200,60,0.14),
        2px 2px 0 rgba(255,230,80,0.10) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset,
        0 -4px 12px rgba(0,0,0,0.4) inset;
    }
    .home-card.card-c3:hover {
      transform: translateY(-2px);
      box-shadow:
        8px 10px 28px rgba(0,0,0,0.90),
        0 0 18px rgba(200,170,30,0.28),
        -1px -1px 4px rgba(240,200,60,0.14),
        2px 2px 0 rgba(255,230,80,0.12) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset;
    }

    /* Card 4: ইর-রেগুলার মহাজন — Malachite/Forest */
    .home-card.card-c4 {
      background:
        radial-gradient(ellipse at 55% 15%, rgba(80,180,140,0.16) 0%, transparent 50%),
        var(--mat-malachite);
      border: 2px solid rgba(60,160,110,0.60);
      box-shadow:
        6px 6px 20px rgba(0,0,0,0.85),
        -1px -1px 4px rgba(80,180,140,0.08),
        2px 2px 0 rgba(100,200,160,0.08) inset,
        -2px -2px 0 rgba(0,0,0,0.60) inset,
        0 -4px 12px rgba(0,0,0,0.45) inset;
    }
    .home-card.card-c4:hover {
      transform: translateY(-2px);
      box-shadow:
        8px 10px 28px rgba(0,0,0,0.90),
        0 0 18px rgba(60,150,100,0.22),
        -1px -1px 4px rgba(80,180,140,0.08),
        2px 2px 0 rgba(100,200,160,0.10) inset,
        -2px -2px 0 rgba(0,0,0,0.60) inset;
    }

    /* Card 5: Aggregate Report — Slate/Indigo */
    .home-card.card-c5 {
      background:
        radial-gradient(ellipse at 35% 15%, rgba(120,140,220,0.20) 0%, transparent 50%),
        var(--mat-slate-indigo);
      border: 2px solid rgba(130,150,210,0.65);
      box-shadow:
        6px 6px 20px rgba(0,0,0,0.85),
        -1px -1px 4px rgba(140,160,220,0.10),
        2px 2px 0 rgba(160,180,240,0.10) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset,
        0 -4px 12px rgba(0,0,0,0.4) inset;
    }
    .home-card.card-c5:hover {
      transform: translateY(-2px);
      box-shadow:
        8px 10px 28px rgba(0,0,0,0.90),
        0 0 18px rgba(110,130,210,0.25),
        -1px -1px 4px rgba(140,160,220,0.10),
        2px 2px 0 rgba(160,180,240,0.12) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset;
    }

    /* Card 6: Profit & Loss Trends — Crimson/Copper */
    .home-card.card-c6 {
      background:
        radial-gradient(ellipse at 50% 15%, rgba(220,110,80,0.20) 0%, transparent 50%),
        var(--mat-crimson-copper);
      border: 2px solid rgba(200,110,70,0.70);
      box-shadow:
        6px 6px 20px rgba(0,0,0,0.85),
        -1px -1px 4px rgba(220,130,90,0.10),
        2px 2px 0 rgba(240,150,100,0.10) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset,
        0 -4px 12px rgba(0,0,0,0.4) inset;
    }
    .home-card.card-c6:hover {
      transform: translateY(-2px);
      box-shadow:
        8px 10px 28px rgba(0,0,0,0.90),
        0 0 18px rgba(210,110,70,0.28),
        -1px -1px 4px rgba(220,130,90,0.10),
        2px 2px 0 rgba(240,150,100,0.12) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset;
    }

    /* Card 7: Fund Flow Overview — Aqua/Cyan Flow */
    .home-card.card-c7 {
      background:
        radial-gradient(ellipse at 45% 15%, rgba(80,200,220,0.22) 0%, transparent 50%),
        var(--mat-aqua-cyan);
      border: 2px solid rgba(80,190,210,0.70);
      box-shadow:
        6px 6px 20px rgba(0,0,0,0.85),
        -1px -1px 4px rgba(100,210,225,0.12),
        2px 2px 0 rgba(130,230,240,0.10) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset,
        0 -4px 12px rgba(0,0,0,0.4) inset;
    }
    .home-card.card-c7:hover {
      transform: translateY(-2px);
      box-shadow:
        8px 10px 28px rgba(0,0,0,0.90),
        0 0 18px rgba(80,190,210,0.30),
        -1px -1px 4px rgba(100,210,225,0.12),
        2px 2px 0 rgba(130,230,240,0.12) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset;
    }

    /* Card 8: পাইকারি Report — Amethyst/Royal Purple */
    .home-card.card-c8 {
      background:
        radial-gradient(ellipse at 40% 15%, rgba(170,110,220,0.22) 0%, transparent 50%),
        var(--mat-amethyst);
      border: 2px solid rgba(170,120,220,0.70);
      box-shadow:
        6px 6px 20px rgba(0,0,0,0.85),
        -1px -1px 4px rgba(190,140,230,0.12),
        2px 2px 0 rgba(210,160,240,0.10) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset,
        0 -4px 12px rgba(0,0,0,0.4) inset;
    }
    .home-card.card-c8:hover {
      transform: translateY(-2px);
      box-shadow:
        8px 10px 28px rgba(0,0,0,0.90),
        0 0 18px rgba(170,110,220,0.30),
        -1px -1px 4px rgba(190,140,230,0.12),
        2px 2px 0 rgba(210,160,240,0.12) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset;
    }

    /* Card 9: ডাটাবেইজ সংযোগ — Sapphire/Cloud Blue */
    .home-card.card-c9 {
      background:
        radial-gradient(ellipse at 40% 15%, rgba(80,140,230,0.22) 0%, transparent 50%),
        var(--mat-sapphire);
      border: 2px solid rgba(90,150,230,0.70);
      box-shadow:
        6px 6px 20px rgba(0,0,0,0.85),
        -1px -1px 4px rgba(110,170,240,0.12),
        2px 2px 0 rgba(140,190,250,0.10) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset,
        0 -4px 12px rgba(0,0,0,0.4) inset;
    }
    .home-card.card-c9:hover {
      transform: translateY(-2px);
      box-shadow:
        8px 10px 28px rgba(0,0,0,0.90),
        0 0 18px rgba(80,140,230,0.30),
        -1px -1px 4px rgba(110,170,240,0.12),
        2px 2px 0 rgba(140,190,250,0.12) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset;
    }

    /* Card 10: পার্টি — Amber/Gold */
    .home-card.card-c10 {
      background:
        radial-gradient(ellipse at 40% 15%, rgba(230,170,70,0.22) 0%, transparent 50%),
        var(--mat-amber-gold);
      border: 2px solid rgba(230,180,90,0.70);
      box-shadow:
        6px 6px 20px rgba(0,0,0,0.85),
        -1px -1px 4px rgba(240,195,110,0.12),
        2px 2px 0 rgba(250,210,140,0.10) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset,
        0 -4px 12px rgba(0,0,0,0.4) inset;
    }
    .home-card.card-c10:hover {
      transform: translateY(-2px);
      box-shadow:
        8px 10px 28px rgba(0,0,0,0.90),
        0 0 18px rgba(230,170,70,0.30),
        -1px -1px 4px rgba(240,195,110,0.12),
        2px 2px 0 rgba(250,210,140,0.12) inset,
        -2px -2px 0 rgba(0,0,0,0.55) inset;
    }

    .card-body {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 8px 4px 10px;
      gap: 3px;
      min-height: 100px;
      position: relative;
      z-index: var(--z-local);
    }
    /* আইকন সার্কেল */
    /* ঘূর্ণায়মান মেডেলিয়ন র‍্যাপার */
    .icon-medallion {
      width: 40px; height: 40px;
      border-radius: var(--radius-circle);
      margin-bottom: 4px;
      display: flex; align-items: center; justify-content: center;
      position: relative;
      margin-top: 2px;
    }

    /* স্থির বাইরের রিং (অ্যানিমেশন বন্ধ) */
    .icon-medallion::before {
      content: '';
      position: absolute;
      inset: -3px;
      border-radius: var(--radius-circle);
      background:
        conic-gradient(
          rgba(200,160,60,0.4) 0deg 30deg, transparent 30deg 60deg,
          rgba(200,160,60,0.4) 60deg 90deg, transparent 90deg 120deg,
          rgba(200,160,60,0.4) 120deg 150deg, transparent 150deg 180deg,
          rgba(200,160,60,0.4) 180deg 210deg, transparent 210deg 240deg,
          rgba(200,160,60,0.4) 240deg 270deg, transparent 270deg 300deg,
          rgba(200,160,60,0.4) 300deg 330deg, transparent 330deg 360deg
        );
    }

    /* আইকন ইনার সার্কেল */
    .icon-medallion .icon-inner {
      position: relative;
      z-index: var(--z-sticky);
      width: 34px; height: 34px;
      border-radius: var(--radius-circle);
      display: flex; align-items: center; justify-content: center;
      font-size: 14px;
    }

    /* আইকন ইনার — shared base shadow, color per-card */
    .icon-inner {
      box-shadow:
        3px 3px 10px rgba(0,0,0,0.7),
        -2px -2px 6px rgba(240,180,80,0.15) inset,
        2px 2px 6px rgba(0,0,0,0.5) inset;
    }
    /* Bronze — card-c1 */
    .card-c1 .icon-inner {
      background: var(--icon-bronze-radial), var(--icon-bronze-linear);
      border: 2px solid rgba(220,160,60,0.7);
      color: var(--icon-bronze-text);
    }
    /* Steel — card-c2 */
    .card-c2 .icon-inner {
      background: var(--icon-steel-radial), var(--icon-steel-linear);
      border: 2px solid rgba(120,160,190,0.5);
      color: var(--icon-steel-text);
    }
    /* Brass — card-c3 */
    .card-c3 .icon-inner {
      background: var(--icon-brass-radial), var(--icon-brass-linear);
      border: 2px solid rgba(210,180,60,0.7);
      color: var(--icon-brass-text);
    }
    /* Patina — card-c4 */
    .card-c4 .icon-inner {
      background: var(--icon-patina-radial), var(--icon-patina-linear);
      border: 2px solid rgba(100,180,150,0.5);
      color: var(--icon-patina-text);
    }
    /* Indigo — card-c5 */
    .card-c5 .icon-inner {
      background: var(--icon-indigo-radial), var(--icon-indigo-linear);
      border: 2px solid rgba(140,160,220,0.55);
      color: var(--icon-indigo-text);
    }
    /* Copper — card-c6 */
    .card-c6 .icon-inner {
      background: var(--icon-copper-radial), var(--icon-copper-linear);
      border: 2px solid rgba(220,140,100,0.6);
      color: var(--icon-copper-text);
    }
    /* Aqua — card-c7 */
    .card-c7 .icon-inner {
      background: var(--icon-aqua-radial), var(--icon-aqua-linear);
      border: 2px solid rgba(100,210,225,0.6);
      color: var(--icon-aqua-text);
    }
    /* Amethyst — card-c8 */
    .card-c8 .icon-inner {
      background: var(--icon-amethyst-radial), var(--icon-amethyst-linear);
      border: 2px solid rgba(190,140,230,0.6);
      color: var(--icon-amethyst-text);
    }
    /* Sapphire — card-c9 */
    .card-c9 .icon-inner {
      background: var(--icon-sapphire-radial), var(--icon-sapphire-linear);
      border: 2px solid rgba(110,170,240,0.6);
      color: var(--icon-sapphire-text);
    }

    .card-title {
      font-family: var(--fab-serif);
      font-size: var(--font-xs);
      font-weight: 700;
      text-align: center;
      line-height: 1.2;
      margin-bottom: 1px;
      /* Polished brass engraved text */
      background: var(--gradient-gold-btn);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      filter:
        drop-shadow(0 1px 2px rgba(0,0,0,0.80))
        drop-shadow(0 2px 5px rgba(0,0,0,0.60));
      position: relative;
      z-index: var(--z-local);
    }
    .card-count {
      font-size: var(--font-2xs);
      font-weight: 700;
      color: var(--dw-gold-text);
      text-align: center;
      min-height: 10px;
      position: relative;
      z-index: var(--z-local);
      text-shadow: 0 1px 3px rgba(0,0,0,0.7);
    }

    /* SIDE MENU
    */
    .menu-overlay {
      display: none;
      position: fixed; inset: 0;
      background: rgba(0,0,0,.35);
      z-index: var(--z-overlay-mid);
    }
    .menu-overlay.open { display: block; }

    .side-menu {
      position: fixed;
      top: 0; right: 0;
      width: 280px;
      height: 100vh;
      border-left: 2px solid rgba(200,150,30,0.45);
      box-shadow: -12px 0 40px rgba(0,0,0,.55);
      z-index: var(--z-overlay-high);
      display: flex;
      flex-direction: column;
      transform: translateX(100%);
      transition: transform var(--dur-lg-alt) var(--ease-out-soft);
      background-color: var(--dw-cream-alt) !important;
      background-image: none !important;
    }
    .side-menu.open { transform: translateX(0); }

    .side-menu-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 18px 20px;
      position: relative;
      background: linear-gradient(180deg, var(--dw-cream-header-alt) 0%, var(--dw-cream-alt) 100%);
      border-bottom: 1px solid rgba(184,144,42,.22);
    }
    .side-menu-head::after {
      content: '';
      position: absolute;
      left: 12px; right: 12px; bottom: -1px;
      height: 1px;
      background: linear-gradient(90deg,
        transparent 0%,
        rgba(184,144,42,0.30) 20%,
        rgba(184,144,42,0.45) 50%,
        rgba(184,144,42,0.30) 80%,
        transparent 100%
      );
    }
    .side-menu-title {
      font-size: 16px; font-weight: 800; letter-spacing: .4px;
      color: var(--dw-ink-deep);
      text-shadow: 0 1px 0 rgba(255,255,255,0.70), 0 -1px 0 rgba(0,0,0,0.12);
    }
    .menu-close-btn {
      width: 30px; height: 30px;
      border-radius: var(--radius-lg); border: 1px solid rgba(184,144,42,.30);
      background: rgba(184,144,42,.10);
      color: var(--dw-amber-text); -webkit-text-fill-color: var(--dw-amber-text); font-size: 18px;
      cursor: pointer; display: flex; align-items: center; justify-content: center;
      transition: background var(--dur-base), transform var(--dur-base);
    }
    .menu-close-btn:hover { background: rgba(184,144,42,.20); transform: scale(1.15); }

    /* UTILITY CLASSES */
    /* dark panel engraved text — সাইড মেনু ও হেডার */
    .text-engraved {
      color: rgba(60,32,8,0.92);
      text-shadow:
        0 1px 0 rgba(255,210,80,0.20),
        0 -1px 0 rgba(0,0,0,0.85),
        1px 0 0 rgba(0,0,0,0.60),
        -1px 0 0 rgba(255,200,60,0.12);
    }
    .side-menu-body {
      padding: 14px 12px;
      display: flex;
      flex-direction: column;
      gap: 6px;
      overflow-y: auto;
      flex: 1;
    }
    .menu-item {
      font-family: var(--fab-sans);
      display: flex;
      align-items: center;
      gap: 14px;
      width: 100%;
      padding: 13px 14px;
      background: transparent;
      border: none;
      border-bottom: 1px solid transparent;
      border-image: none;
      border-radius: 0;
      cursor: pointer;
      text-align: left;
      transition: background var(--dur-base);
      position: relative;
    }
    .menu-item::after {
      content: '';
      position: absolute;
      left: 10px; right: 10px; bottom: 0;
      height: 1px;
      background: linear-gradient(90deg,
        transparent 0%,
        rgba(184,144,42,0.20) 20%,
        rgba(184,144,42,0.30) 50%,
        rgba(184,144,42,0.20) 80%,
        transparent 100%
      );
    }
    .menu-item:last-child::after { display: none; }
    .menu-item:hover { background: rgba(184,144,42,.10); border-radius: var(--radius-lg); }

    /* SHARED WOOD PANEL BACKGROUND
       (side-menu, ep-sheet, fv-screen,
        fv-edit-modal, fv-detail-screen
        সবাই এই একটা class শেয়ার করে)
    */
    .wood-panel-bg {
      background-color: var(--dz-canvas);
      background-image: none;
    }

    /* ফর্ম বক্স */
    .ep-form-box {
      background: rgba(240,232,208,.55);
      border: 1px solid rgba(184,144,42,.3);
      border-radius: var(--radius-3xl);
      padding: 12px 12px 10px;
      display: flex; flex-direction: column; gap: 8px;
      flex-shrink: 0;
    }
    .ep-row { display: flex; gap: 8px; }

    /* Floating Label — ep */
    /* ep-field: fieldset/legend floating label */
    .ep-field {
      position: relative; flex: 1; min-width: 0; margin-top: 10px;
      display: flex; flex-direction: column;
    }
    .ep-field fieldset {
      border: 1.5px solid rgba(184,144,42,.35);
      border-radius: var(--radius-lg);
      padding: 0;
      margin: 0;
      background: var(--dw-cream-soft);
      transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
      min-width: 0;
    }
    .ep-field fieldset:focus-within {
      border-color: var(--gold2);
    }
    /* legend — বর্ডার কাটার জন্য, দেখা যায় না */
    .ep-field legend {
      font-family: var(--fab-sans);
      font-size: var(--font-xs); font-weight: 700;
      color: transparent; /* নিজে invisible */
      padding: 0;
      margin-left: 7px;
      line-height: 0; /* উচ্চতা শূন্য — বর্ডার নড়বে না */
      max-width: 0; /* ইনপুটে ভ্যালু না থাকলে gap বন্ধ */
      white-space: nowrap;
      overflow: hidden;
      transition: max-width var(--dur-base), padding var(--dur-base);
    }
    /* label — floating */
    .ep-label {
      position: absolute;
      left: 9px; top: 50%; transform: translateY(-50%);
      font-size: 11.5px; font-weight: 500; color: var(--dw-meta-brown-light);
      pointer-events: none;
      transition: top var(--dur-base), transform var(--dur-base), font-size var(--dur-base), color var(--dur-base);
      line-height: 1;
    }
    /* focused বা value আছে → label উপরে, legend খোলে */
    .ep-field fieldset:focus-within legend,
    .ep-field.has-val legend {
      max-width: fit-content;
      padding: 0 4px;
    }
    .ep-field fieldset:focus-within ~ .ep-label,
    .ep-field.has-val .ep-label {
      top: 0; transform: translateY(-50%);
      font-size: var(--font-xs); font-weight: 700;
      color: var(--gold);
      left: 11px;
    }
    .ep-field fieldset:focus-within ~ .ep-label { color: var(--gold2); }
    .ep-inp {
      font-family: var(--fab-sans);
      padding: 9px 9px 8px;
      border: none; outline: none;
      font-size: 13px; color: var(--dw-ink-warm-alt);
      background: transparent;
      width: 100%;
      border-radius: var(--radius-md);
      display: block;
    }
    .ep-inp.amt { text-align: right; }
    /* মোবাইল +880 prefix */
    .ep-mob-wrap {
      display: flex; align-items: center;
      border: 1.5px solid rgba(184,144,42,.35);
      border-radius: var(--radius-lg); background: var(--dw-cream-soft); overflow: hidden;
      transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
    }
    .ep-mob-wrap:focus-within { border-color: var(--gold2); }
    .ep-mob-prefix {
      font-size: 12px; font-weight: 700; color: var(--dw-meta-brown-light);
      padding: 0 5px 0 9px; white-space: nowrap; flex-shrink: 0;
      position: relative; line-height: 1;
      align-self: stretch;
      display: flex; align-items: center;
    }
    .ep-mob-prefix::after {
      content: '';
      position: absolute;
      right: 0; top: 50%; transform: translateY(-50%);
      width: 1px; height: 18px;
      background:
        linear-gradient(to bottom,
          rgba(184,144,42,.55) 0px,  rgba(184,144,42,.55) 4px,
          transparent 4px,           transparent 7px,
          rgba(184,144,42,.55) 7px,  rgba(184,144,42,.55) 11px,
          transparent 11px,          transparent 14px,
          rgba(184,144,42,.55) 14px, rgba(184,144,42,.55) 18px
        );
    }
    .ep-mob-wrap .ep-inp { border: none; border-radius: 0; padding-left: 5px; box-shadow: none; flex: 1; background: transparent; }
    .ep-mob-wrap .ep-inp:focus { border: none; box-shadow: none; background: transparent; }
    .ep-foot {
      display: flex; align-items: center;
      justify-content: space-between;
      margin-top: 2px;
    }
    .ep-back-btn {
      width: 38px; height: 38px; border-radius: var(--radius-circle);
      border: 1.5px solid rgba(184,144,42,.35);
      background: rgba(240,232,208,.7);
      color: var(--dw-brown-text); -webkit-text-fill-color: var(--dw-brown-text);
      font-size: 16px; font-weight: 700;
      display: flex; align-items: center; justify-content: center;
      cursor: pointer;
      transition: background var(--dur-fast), border-color var(--dur-fast);
      box-shadow: 0 2px 6px rgba(0,0,0,.12);
      flex-shrink: 0;
    }
    .ep-back-btn:hover { background: rgba(220,180,80,.25); border-color: var(--gold2); }
    .ep-save-btn {
      font-family: var(--fab-sans);
      padding: 9px 20px; border-radius: var(--radius-xl);
      border: 1.5px solid rgba(184,144,42,.4);
      background: var(--gold2); color: var(--ink);
      font-size: 13px; font-weight: 700; cursor: pointer;
      display: flex; align-items: center; gap: 6px;
      transition: background var(--dur-fast);
      box-shadow: 0 2px 8px rgba(184,144,42,.25);
    }
    .ep-save-btn:hover { background: var(--dw-save-hover); }

    /* ফুলস্ক্রিন খোলা থাকলে tab bar লুকাই */
    body:has(.fv-screen.open) .bottom-tab-bar,
    body:has(.fv-detail-screen.open) .bottom-tab-bar {
      opacity: 0;
      pointer-events: none;
      transform: translateY(100%);
      transition: opacity var(--dur-md), transform var(--dur-lg);
    }
    .bottom-tab-bar {
      transition: opacity var(--dur-md), transform var(--dur-lg);
    }

    /* ফুল স্ক্রিন লিস্ট ভিউ */
    .fv-screen {
      display: flex;
      position: fixed; inset: 0;
      z-index: var(--z-modal);
      isolation: isolate;
      flex-direction: column;
      overflow: hidden;
      height: 100dvh;
      transform: translateX(100%);
      transition: none;
      will-change: auto;
      pointer-events: none;
      visibility: hidden;
      contain: layout style paint;
    }
    .fv-screen.open {
      transform: translateX(0);
      pointer-events: auto;
      visibility: visible;
      will-change: auto;
    }

    /* কার্ড ক্লিকের পার্সন ডেটা স্ক্রিন — ক্রিম অফ হোয়াইট ব্যাকগ্রাউন্ড */
    .fv-screen.wood-panel-bg {
      background-color: var(--dz-canvas) !important;
      background-image: none !important;
    }

    .fv-header {
      background: var(--dz-surface-soft);
      border-bottom: 1px solid var(--dw-hairline-warm);
      padding: 14px 16px 12px 6px;
      display: flex; flex-direction: column; gap: 10px;
      flex-shrink: 0;
      box-shadow: 0 2px 8px rgba(0,0,0,.08);
      position: relative;
    }
    /* হেডার উপরের সারি: ব্যাক + আইকন + টাইটেল */
    .fv-hdr-top {
      display: flex; align-items: center; justify-content: space-between; gap: 12px;
      position: relative; z-index: var(--z-local);
    }
    .fv-back-btn {
      width: 34px; height: 34px;
      background: none;
      border: none;
      border-radius: 0;
      color: var(--dw-brown-dark); -webkit-text-fill-color: var(--dw-brown-dark);
      cursor: pointer;
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
      transition: transform var(--dur-fast);
      filter: none;
    }
    .fv-back-btn:hover { transform: scale(1.15); }
    .fv-hdr-icon {
      width: 50px; height: 50px; border-radius: var(--radius-2xl);
      border: none; flex-shrink: 0;
      display: flex; align-items: center; justify-content: center;
      filter: none;
    }
    .fv-hdr-title {
      font-size: 15px; font-weight: 800;
      color: var(--dw-ink-warm);
      line-height: 1.2;
      text-shadow: none;
    }
    .fv-hdr-sub {
      font-size: var(--font-xs);
      color: var(--dw-sage-text);
      margin-top: 2px;
    }

    /* সার্চ বার — হেডারের ভেতরে */
    .fv-search-wrap {
      position: relative; z-index: var(--z-local);
    }
    .fv-search {
      font-family: var(--fab-sans);
      width: 100%; padding: 8px 12px 8px 36px;
      border: 1.5px solid var(--dw-input-border);
      border-radius: var(--radius-xl);
      font-size: 13px; color: var(--dw-ink-warm);
      background: var(--dw-input-bg); outline: none;
      transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
      background-image: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 24 24' fill='none' stroke='%237a8c7e' stroke-width='2' stroke-linecap='round' stroke-linejoin='round' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='11' cy='11' r='8'/%3E%3Cline x1='21' y1='21' x2='16.65' y2='16.65'/%3E%3C/svg%3E");
      background-repeat: no-repeat;
      background-position: 10px center;
    }
    .fv-search:focus { border-color: var(--dw-input-focus); }

    /* লিস্ট বডি */
    .fv-body {
      flex: 1; min-height: 0; overflow-y: auto;
      -webkit-overflow-scrolling: touch;
      padding: 10px 12px 30px;
      display: flex; flex-direction: column; gap: 8px;
      scroll-behavior: auto;
      overscroll-behavior: contain;
    }
    /* স্ক্রলবার স্টাইল */
    .fv-body::-webkit-scrollbar { width: 4px; }
    .fv-body::-webkit-scrollbar-track { background: transparent; }
    .fv-body::-webkit-scrollbar-thumb { background: rgba(184,144,42,.35); border-radius: var(--radius-sm); }
    .fv-body::-webkit-scrollbar-thumb:hover { background: rgba(184,144,42,.6); }
    .fv-empty {
      text-align: center; padding: 40px 20px;
      font-size: 14px; color: var(--dw-meta-brown-light);
    }
    .fv-card {
      background: var(--dw-cream-input);
      border: 1.5px solid var(--dw-input-border-alt);
      border-radius: var(--radius-4xl-alt);
      overflow: hidden;
      box-shadow: 0 2px 8px rgba(0,0,0,.10);
      transition: border-color var(--dur-fast), box-shadow var(--dur-md), transform var(--dur-fast), opacity var(--dur-fast);
      flex-shrink: 0;
      contain: layout style;
      touch-action: pan-y;
      user-select: none;
      -webkit-user-select: none;
    }
    .fv-card:hover { border-color: var(--dw-hover-border); }

    /* ড্র্যাগ হ্যান্ডেল — lp-selected অবস্থায় দেখা যাবে */
    .fv-drag-handle {
      position: absolute;
      top: 0; left: 0;
      width: 28px; height: 100%;
      display: flex; align-items: center; justify-content: center;
      cursor: grab;
      opacity: 0;
      transition: opacity var(--dur-md);
      z-index: var(--z-sticky);
      touch-action: none;
    }
    .fv-drag-handle svg { color: var(--dw-drag-icon); pointer-events: none; }
    .fv-card.lp-selected .fv-drag-handle { opacity: 1; }

    /* ড্র্যাগিং অবস্থা */
    .fv-card.dragging {
      opacity: 0.88;
      box-shadow: 0 16px 40px rgba(0,0,0,0.40), 0 0 0 2.5px var(--gold);
      border-color: var(--gold);
      z-index: var(--z-drawer);
      transform: scale(1.03) rotate(0.5deg);
      background: var(--dw-cream-bright);
      position: fixed !important;
      pointer-events: none;
    }

    /* ড্রপ প্লেসহোল্ডার */
    .fv-card-placeholder {
      border-radius: var(--radius-4xl-alt);
      background: repeating-linear-gradient(
        45deg,
        rgba(200,150,30,0.08),
        rgba(200,150,30,0.08) 6px,
        transparent 6px,
        transparent 12px
      );
      border: 2px dashed rgba(200,150,30,0.45);
      flex-shrink: 0;
    }

    /* লং প্রেস রিপল */
    @keyframes lp-pulse {
      0%   { box-shadow: 0 2px 8px rgba(0,0,0,.10), 0 0 0 0   rgba(200,150,30,0.55); }
      65%  { box-shadow: 0 2px 8px rgba(0,0,0,.10), 0 0 0 10px rgba(200,150,30,0);   }
      100% { box-shadow: 0 2px 8px rgba(0,0,0,.10), 0 0 0 0   rgba(200,150,30,0);    }
    }
    .fv-card.lp-pulse { animation: lp-pulse .45s ease-out; }
    .fv-card-top {
      position: relative;
      padding: 12px 14px 10px 14px;
      cursor: pointer;
      transition: padding-left var(--dur-md);
    }
    .fv-card.lp-selected .fv-card-top { padding-left: 32px; }
    .fv-card-top:hover { background: rgba(0,0,0,.04); }
    .fv-card-left { min-width: 0; padding-right: 105px; }
    .fv-name { font-size: 14px; font-weight: 800; color: var(--dw-ink-warm-alt); }
    .fv-contact-line { display: flex; align-items: center; gap: 5px; font-size: 11px; color: var(--dw-contact-text); margin-top: 5px; line-height: 1.5; }
    .fv-contact-line svg { flex-shrink: 0; }
    .fv-top-actions {
      position: absolute;
      top: 10px; right: 12px;
      display: flex; flex-direction: column; gap: 4px;
      align-items: flex-end;
    }
    .fv-top-btns-row {
      display: flex; flex-direction: row; gap: 5px; align-items: center;
    }
    .fv-phone-btn {
      display: inline-flex; align-items: center; justify-content: center;
      width: 36px; height: 36px; border-radius: var(--radius-md);
      border: 1.5px solid rgba(34,197,94,.45);
      background: rgba(34,197,94,.12); color: var(--dw-success-green); -webkit-text-fill-color: var(--dw-success-green);
      text-decoration: none;
      transition: background var(--dur-xs);
      flex-shrink: 0;
    }
    .fv-phone-btn:hover { background: rgba(34,197,94,.24); }
    .fv-wa-btn {
      display: inline-flex; align-items: center; justify-content: center;
      width: 36px; height: 36px; border-radius: var(--radius-md);
      border: 1.5px solid rgba(37,211,102,.4);
      background: rgba(37,211,102,.1); color: var(--dw-success-teal); -webkit-text-fill-color: var(--dw-success-teal);
      text-decoration: none;
      transition: background var(--dur-xs);
      flex-shrink: 0;
    }
    .fv-wa-btn:hover { background: rgba(37,211,102,.22); }
    .fv-edit-btn {
      display: inline-flex; align-items: center; justify-content: center;
      width: 36px; height: 36px; border-radius: var(--radius-md);
      border: 1.5px solid rgba(184,144,42,.4);
      background: rgba(184,144,42,.1); color: var(--gold); -webkit-text-fill-color: var(--gold);
      cursor: pointer;
      transition: background var(--dur-xs);
      flex-shrink: 0;
    }
    .fv-edit-btn:hover { background: rgba(184,144,42,.22); }

    /* DEBTORS LIST স্ক্রিন
    */

    /* DASHBOARD MODE — header partial hide */
    .agg-inline-table {
      width: 100%;
      border-collapse: collapse;
      font-size: 11px;
      font-family: var(--fab-sans);
    }
    .agg-inline-table th {
      padding: 8px 6px;
      text-align: right;
      color: var(--text3, #888);
      font-weight: 600;
      letter-spacing: 0.02em;
      border-bottom: 1px solid var(--border, #e5e5e5);
      white-space: nowrap;
    }
    .agg-inline-table th:first-child { text-align: left; }
    .agg-inline-table td {
      padding: 9px 6px;
      text-align: right;
      border-bottom: 1px solid var(--border, #f0f0f0);
      color: var(--text, #222);
      white-space: nowrap;
    }
    .agg-inline-table td:first-child { text-align: left; font-weight: 600; color: var(--text2,#555); }
    .agg-inline-table tbody tr:last-child td { border-bottom: none; }
    .agg-inline-table tbody tr:hover td { background: rgba(204,120,92,0.04); }
    .agg-inline-table tfoot td {
      padding: 9px 6px;
      border-top: 1.5px solid var(--text, #222);
      font-weight: 700;
      color: var(--text, #222);
      background: var(--bg, #f5f0eb);
    }
    .agg-td-sales   { color: var(--text, #222)   !important; font-weight: 600; }
    .agg-td-gross   { color: var(--text, #222)   !important; font-weight: 600; }
    .agg-td-net-pos { color: var(--dz-success)             !important; font-weight: 700; }
    .agg-td-net-neg { color: var(--dw-loss-red-alt)             !important; font-weight: 700; }
    .agg-td-in      { color: var(--text2, #555)  !important; }
    .agg-td-out     { color: var(--text2, #555)  !important; }

    /* প্রফিট stat কার্ড */
    .profit-kpi-card {
      border-radius: var(--radius-3xl);
      padding: 16px 12px 16px;
      box-shadow: none;
      display: flex;
      flex-direction: column;
      justify-content: center;
      gap: 6px;
      min-height: 118px;
      min-width: 0;
      width: 100%;
      box-sizing: border-box;
      overflow: hidden;
    }
    .profit-kpi-label {
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.01em;
      line-height: 1.35;
      font-family: var(--fab-sans);
      overflow: visible;
      text-overflow: clip;
      white-space: normal;
      word-break: keep-all;
      overflow-wrap: break-word;
    }
    .profit-kpi-value {
      font-size: clamp(14px, 17px, 19px);
      font-weight: 800;
      line-height: 1.2;
      font-family: var(--fab-sans);
      letter-spacing: -0.01em;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
      max-width: 100%;
    }
    .profit-kpi-net {
      background: var(--dz-surface-card);
      border: 1px solid var(--dz-hairline);
    }
    .profit-kpi-net .profit-kpi-label { color: var(--dz-muted); }
    .profit-kpi-net .profit-kpi-value { color: var(--dz-success); }
    .profit-kpi-gross {
      background: var(--dz-surface-card);
      border: 1px solid var(--dz-hairline);
    }
    .profit-kpi-gross .profit-kpi-label { color: var(--dz-muted); }
    .profit-kpi-gross .profit-kpi-value { color: var(--dz-ink); }
    /* লোকসান হলে লাল */
    .profit-kpi-value.is-loss { color: var(--dw-loss-red-alt) !important; }

    /* home-kpi-strip — header-এর ভেতরে, নিচে overflow হয়ে বের হয় (এটা হোম ট্যাবের KPI স্ট্রিপ) */
    .home-kpi-strip {
      display: none;
      position: relative;
      z-index: var(--z-raised);
      margin-bottom: 10px;
      padding: 4px 10px 0;
    }
    body.show-home .home-kpi-strip              { display: grid; }
    body.show-home .kpi-strip:not(.home-kpi-strip) { display: none; }
    body.show-home #dashFundFlowCard                { display: none; }
    /* Fund Flow কার্ড এবং তার নিচের সাপ্তাহিক আপডেট কার্ডের মাঝে আগের মতো সামান্য গ্যাপ */
    #dashFundFlowCard { margin-bottom: 5px; }
    #dashWeeklyUpdateWelcomeCard { margin-top: 6px; }
    body.show-home #dashAggCard                      { display: none; }
    body.show-home #dashWeeklyUpdateWelcomeCard         { display: none !important; }

    /* কাপড় ক্রয় হিসাব — FABRIC OVERLAY
       (Claude cream/coral/navy design system)
    */
    #fabricOverlay {
      --fab-canvas: var(--dz-canvas, var(--dz-canvas, #faf9f5));
      --fab-surface-card: var(--dz-surface-card, #efe9de);
      --fab-surface-strong: var(--dz-surface-strong, #e8e0d2);
      --fab-surface-dark: #181715;
      --fab-surface-dark-elev: #252320;
      --fab-ink: var(--dz-ink, #141413);
      --fab-body: var(--dz-body, #3d3d3a);
      --fab-muted: var(--dz-muted, #6c6a64);
      --fab-muted-soft: var(--dz-muted-soft, #8e8b82);
      --fab-hairline: var(--dz-hairline, #e6dfd8);
      --fab-coral: var(--dz-primary, #cc785c);
      --fab-coral-active: var(--dz-primary-active, #a9583e);
      --fab-teal: #5db8a6;
      --fab-amber: #e8a55a;
      --fab-serif: 'Noto Serif Bengali', Georgia, 'Tiempos Headline', 'EB Garamond', serif;
      --fab-sans: 'Noto Sans Bengali', -apple-system, 'StyreneB', 'Inter', sans-serif;
      --fab-mono: 'JetBrains Mono', 'IBM Plex Mono', ui-monospace, monospace;
      background: var(--fab-canvas) !important;
    }
    .fab-label {
      display: block;
      font-size: 11px;
      font-weight: 600;
      color: var(--fab-muted);
      margin-bottom: 5px;
      font-family: var(--fab-sans);
      letter-spacing: 0.02em;
    }
    .fab-input {
      border: 1.5px solid var(--fab-hairline);
      border-radius: var(--radius-lg);
      padding: 10px 12px;
      font-size: 13px;
      font-family: var(--fab-sans);
      background: var(--dw-white-full);
      color: var(--fab-ink);
      outline: none;
      transition: border-color var(--dur-md), box-shadow var(--dur-md);
    }
    .fab-input:focus {
      border-color: var(--fab-coral);
      box-shadow: 0 0 0 3px rgba(204,120,92,0.15);
    }
    .fab-total-cell { font-weight: 700; color: var(--fab-coral-active); font-family: var(--fab-mono); }
    .fab-del-btn {
      background: none; border: none; cursor: pointer;
      color: var(--dz-error); -webkit-text-fill-color: var(--dz-error); font-size: 16px; padding: 2px 6px;
      border-radius: var(--radius-base); transition: background var(--dur-fast);
    }
    .fab-del-btn:active { background: rgba(198,69,69,0.1); }
    .fab-dca-form td { border-top: 1px dashed var(--fab-hairline); }
    /* কার্ড-স্টাইল গ্রুপ (কাপড়ের নাম হেডার) — cream-card + coral accent */
    .fab-group-card {
      background: var(--fab-surface-card);
      border-radius: var(--radius-3xl);
      margin: 10px 0;
      overflow: hidden;
      border: 1px solid var(--fab-hairline);
    }
    .fab-group-head {
      padding: 12px 14px 10px;
      display: flex; align-items: center; justify-content: space-between;
      flex-wrap: wrap; gap: 8px;
    }
    .fab-group-title {
      font-family: var(--fab-serif);
      font-size: 16px;
      font-weight: 400;
      color: var(--fab-ink);
      letter-spacing: -0.2px;
    }
    .fab-group-unit-tag {
      font-size: var(--font-xs); color: var(--fab-muted); font-family: var(--fab-sans);
      margin-left: 6px; font-weight: 500;
    }
    .fab-avg-badge {
      font-size: var(--font-xs); font-weight: 600; font-family: var(--fab-mono);
      background: rgba(232,165,90,0.22); color: var(--dw-amber-badge);
      border-radius: var(--radius-pill); padding: 3px 10px;
    }
    .fab-add-more-btn {
      background: var(--fab-coral); color: var(--dw-white); border: none; border-radius: var(--radius-lg);
      padding: 6px 12px; font-size: 11px; font-weight: 600; cursor: pointer;
      font-family: var(--fab-sans); transition: background var(--dur-fast);
    }
    .fab-add-more-btn:active { background: var(--fab-coral-active); }
    .fab-group-stats {
      display: flex; gap: 14px; flex-wrap: wrap;
      padding: 0 14px 12px;
      font-family: var(--fab-mono);
    }
    .fab-group-stats span { font-size: 11px; color: var(--fab-muted); }
    .fab-group-stats b { color: var(--fab-ink); font-weight: 700; }
    .fab-group-body { background: var(--dw-white-full); }

    /* হোম পেজ — ড্যাশবোর্ড স্ক্রিনের দ্বিতীয় পেজ
    */
    .home-screen-wrap {
      display: flex;
      position: fixed; inset: 0;
      z-index: var(--z-popover);
      flex-direction: column;
      overflow: hidden;
      height: 100dvh;
      background: var(--dw-white-full);
      transform: translateX(100%);
      transition: transform var(--dur-slow) cubic-bezier(.3,.9,.25,1);
      will-change: transform;
      pointer-events: none;
      visibility: hidden;
    }
    body.show-home .home-screen-wrap {
      transform: translateX(0);
      pointer-events: auto;
      visibility: visible;
    }
    .home-screen-body {
      flex: 1;
      overflow-y: auto;
      padding: 0 16px 16px;
      /* padding-top JS-এ header height অনুযায়ী সেট হয় */
      box-sizing: border-box;
    }

    .dl-screen {
      display: flex;
      position: fixed; inset: 0;
      z-index: var(--z-popover);
      flex-direction: column;
      overflow: hidden;
      height: 100dvh;
      background-color: var(--dz-canvas);
      background-image: none;
      transform: translateX(100%);
      transition: none;
      will-change: auto;
      pointer-events: none;
      visibility: hidden;
      isolation: auto;
    }
    /* body.show-ledger হলে dl-screen দেখা যাবে */
    body.show-ledger .dl-screen {
      transform: translateX(0);
      pointer-events: auto;
      visibility: visible;
    }
    /* dl-screen open থাকলে পুরনো .open class backward compat */
    .dl-screen.open {
      transform: translateX(0);
      pointer-events: auto;
      visibility: visible;
    }

    .dl-header {
      background: var(--dz-surface-soft);
      border-bottom: 1px solid var(--dw-hairline-warm);
      padding: 14px 16px 12px 6px;
      display: flex; flex-direction: column; gap: 10px;
      flex-shrink: 0;
      box-shadow: 0 2px 8px rgba(0,0,0,.08);
    }
    .dl-hdr-top {
      display: flex; align-items: center; gap: 10px;
    }
    .dl-hdr-icon {
      width: 44px; height: 44px; border-radius: var(--radius-2xl);
      border: 1.5px solid rgba(155,44,44,.35);
      background: rgba(155,44,44,.1);
      color: var(--dw-red-text);
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
    }
    .dl-hdr-info { flex: 1; min-width: 0; }
    .dl-hdr-title {
      font-size: 15px; font-weight: 800;
      color: var(--dw-ink-warm); line-height: 1.2;
    }
    .dl-hdr-sub {
      font-size: var(--font-xs); color: var(--dw-meta-text-alt); margin-top: 2px;
    }

    /* ফিল্টার ট্যাব */
    .dl-tabs {
      display: flex; gap: 5px;
      overflow-x: auto; padding-bottom: 2px;
      scrollbar-width: none;
    }
    .dl-tabs::-webkit-scrollbar { display: none; }
    .dl-tab {
      font-family: var(--fab-sans);
      font-size: 11px; font-weight: 700;
      padding: 4px 10px;
      border-radius: var(--radius-6xl);
      border: 1.5px solid transparent;
      cursor: pointer;
      white-space: nowrap;
      transition: background var(--dur-xs), border-color var(--dur-xs);
      background: rgba(0,0,0,.06);
      color: var(--dw-brown-mid);
    }
    .dl-tab.active {
      background: rgba(155,44,44,.14);
      border-color: rgba(155,44,44,.40);
      color: var(--dw-red-dark);
    }

    /* সার্চ */
    .dl-search-wrap { position: relative; }
    .dl-search {
      font-family: var(--fab-sans);
      width: 100%; padding: 8px 12px 8px 36px;
      border: 1.5px solid var(--dw-input-border); border-radius: var(--radius-xl);
      font-size: 13px; color: var(--dw-ink-warm);
      background: var(--dw-input-bg); outline: none;
      transition: border-color var(--dur-fast);
      background-image: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 24 24' fill='none' stroke='%237a8c7e' stroke-width='2' stroke-linecap='round' stroke-linejoin='round' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='11' cy='11' r='8'/%3E%3Cline x1='21' y1='21' x2='16.65' y2='16.65'/%3E%3C/svg%3E");
      background-repeat: no-repeat;
      background-position: 10px center;
    }
    .dl-search:focus { border-color: var(--dw-input-focus); }

    /* বডি */
    .dl-body {
      flex: 1; min-height: 0;
      display: flex; flex-direction: column;
      overflow: hidden;
    }
    .dl-table-wrap {
      flex: 1; min-height: 0;
      overflow-x: auto;
      overflow-y: auto;
      -webkit-overflow-scrolling: touch;
      scroll-behavior: auto;
      overscroll-behavior: contain;
    }
    .dl-table-wrap::-webkit-scrollbar { width: 4px; height: 4px; }
    .dl-table-wrap::-webkit-scrollbar-track { background: transparent; }
    .dl-table-wrap::-webkit-scrollbar-thumb { background: rgba(184,144,42,.35); border-radius: var(--radius-sm); }
    .dl-foot {
      display: flex; justify-content: space-between; align-items: center;
      padding: 7px 13px;
      background: rgba(160,130,80,.10);
      border-top: 1px solid rgba(160,130,80,.22);
      flex-shrink: 0;
    }
    .dl-foot-lbl { color: var(--dw-meta-brown); font-size: var(--font-xs); font-weight: 600; }
    .dl-foot-val { color: var(--dw-loss-red); font-weight: 800; font-size: 13px; }
    .dl-empty {
      text-align: center; padding: 40px 20px;
      font-size: 14px; color: var(--dw-meta-brown-light);
    }

    /* এডিট মোডাল */
    .fv-edit-modal-overlay {
      display: none;
      position: fixed; inset: 0;
      background: rgba(0,0,0,.5);
      z-index: var(--z-drawer-high);
      align-items: center;
      justify-content: center;
      padding: 20px;
      contain: layout style paint;
    }
    .fv-edit-modal-overlay.open { display: flex; }
    .fv-edit-modal {
      border: 1.5px solid var(--border);
      border-radius: var(--radius-5xl);
      box-shadow: 0 16px 48px rgba(0,0,0,.25);
      width: 100%; max-width: 380px;
      overflow: hidden;
    }
    .fv-edit-modal-head {
      display: flex; align-items: center; justify-content: space-between;
      padding: 14px 16px;
      background: var(--dw-cream-row);
      border-bottom: 1px solid var(--dw-hairline-warm);
    }
    .fv-edit-modal-title {
      font-size: 13px; font-weight: 800; color: var(--dw-ink-deep);
    }
    .fv-edit-modal-close {
      width: 28px; height: 28px; border-radius: var(--radius-md);
      border: 1px solid rgba(100,70,30,.25);
      background: rgba(0,0,0,.06); color: var(--dw-warm-dark);
      font-size: 15px; cursor: pointer;
      display: flex; align-items: center; justify-content: center;
      transition: background var(--dur-fast);
    }
    .fv-edit-modal-close:hover { background: rgba(0,0,0,.12); }

    /* ডাটাবেইজ ও এপ লক হেডারে স্পষ্ট ব্যাক/ক্লোজ বাটন */
    .modal-close-bold {
      width: 32px; height: 32px; border-radius: var(--radius-lg);
      border: 1.8px solid rgba(200,160,60,.55);
      background: rgba(200,160,60,.12);
      color: var(--dw-gold-mid);
      font-size: 17px; font-weight: 800;
      cursor: pointer;
      display: flex; align-items: center; justify-content: center;
      transition: background var(--dur-fast), transform var(--dur-fast);
      flex-shrink: 0;
    }
    .modal-close-bold:hover { background: rgba(200,160,60,.25); transform: scale(1.08); }
    .fv-edit-modal-body {
      padding: 16px;
      display: flex; flex-direction: column; gap: 10px;
    }
    /* Floating Label — fv-edit (fieldset/legend) */
    .fv-edit-field { position: relative; margin-top: 10px; display: flex; flex-direction: column; }
    .fv-edit-field fieldset {
      border: 1.5px solid rgba(100,70,30,.35);
      border-radius: var(--radius-lg);
      padding: 0; margin: 0;
      background: rgba(255,255,255,.40);
      transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
      min-width: 0;
    }
    .fv-edit-field fieldset:focus-within {
      border-color: var(--gold);
    }
    .fv-edit-field legend {
      font-family: var(--fab-sans);
      font-size: var(--font-2xs); font-weight: 700;
      color: transparent;
      padding: 0; margin-left: 8px;
      line-height: 0;
      max-width: 0;
      white-space: nowrap;
      overflow: hidden;
      transition: max-width var(--dur-base), padding var(--dur-base);
    }
    .fv-edit-field fieldset:focus-within legend,
    .fv-edit-field.has-val legend {
      max-width: fit-content;
      padding: 0 4px;
    }
    .fv-edit-label {
      position: absolute;
      left: 10px; top: 50%; transform: translateY(-50%);
      font-size: 13px; font-weight: 600; color: var(--dw-meta-brown);
      pointer-events: none;
      transition: top var(--dur-base), transform var(--dur-base), font-size var(--dur-base), color var(--dur-base);
      line-height: 1;
    }
    .fv-edit-field fieldset:focus-within ~ .fv-edit-label,
    .fv-edit-field.has-val .fv-edit-label {
      top: 0; transform: translateY(-50%);
      font-size: var(--font-xs); font-weight: 700;
      color: var(--dw-amber-deep);
      left: 12px;
    }
    .fv-edit-field fieldset:focus-within ~ .fv-edit-label { color: var(--gold); }
    .fv-edit-inp {
      font-family: var(--fab-sans);
      padding: 9px 10px 8px;
      border: none; outline: none;
      font-size: 13px; color: var(--dw-ink-warm-alt);
      background: transparent;
      width: 100%;
      border-radius: var(--radius-md);
      display: block;
    }
    .fv-edit-mob-wrap {
      display: flex; align-items: center;
      border: 1.5px solid rgba(100,70,30,.35);
      border-radius: var(--radius-lg); background: rgba(255,255,255,.40); overflow: hidden;
      transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
    }
    .fv-edit-mob-wrap:focus-within { border-color: var(--gold); }
    .fv-edit-mob-prefix {
      font-size: 12px; font-weight: 700; color: var(--dw-meta-brown);
      padding: 0 5px 0 9px; white-space: nowrap; flex-shrink: 0;
      border-right: 1px solid rgba(100,70,30,.20);
      margin: 5px 0; line-height: 1;
    }
    .fv-edit-mob-wrap .fv-edit-inp { border: none; border-radius: 0; padding-left: 6px; box-shadow: none; background: transparent; }
    .fv-edit-modal-foot {
      padding: 0 16px 16px;
      display: flex; gap: 8px; justify-content: flex-end;
    }
    .fv-edit-cancel-btn {
      font-family: var(--fab-sans);
      padding: 8px 16px; border-radius: var(--radius-lg);
      border: 1.5px solid rgba(100,70,30,.25);
      background: rgba(0,0,0,.06); color: var(--dw-warm-dark); -webkit-text-fill-color: var(--dw-warm-dark);
      font-size: 12px; font-weight: 700; cursor: pointer;
      transition: background var(--dur-xs);
    }
    .fv-edit-cancel-btn:hover { background: rgba(0,0,0,.12); }
    .fv-edit-save-btn {
      font-family: var(--fab-sans);
      padding: 8px 20px; border-radius: var(--radius-lg);
      border: 1.5px solid rgba(184,144,42,.4);
      background: var(--gold2); color: var(--ink);
      font-size: 12px; font-weight: 700; cursor: pointer;
      display: flex; align-items: center; gap: 5px;
      transition: background var(--dur-xs);
      box-shadow: 0 2px 8px rgba(184,144,42,.2);
    }
    .fv-edit-save-btn:hover { background: var(--dw-save-hover); }
    /* ডিটেইল ফুলস্ক্রিন উইন্ডো
    */
    .fv-detail-screen {
      display: flex;
      position: fixed; inset: 0;
      background: var(--dz-canvas);
      z-index: var(--z-modal-max);
      flex-direction: column;
      overflow: hidden;
      transform: translateX(100%);
      transition: transform var(--dur-md-alt) var(--ease-out-soft);
      will-change: auto;
      pointer-events: none;
      visibility: hidden;
      contain: layout style paint;
    }
    .fv-detail-screen.open {
      transform: translateX(0);
      pointer-events: auto;
      visibility: visible;
      will-change: transform;
    }
    .fv-detail-header {
      background: var(--dz-surface-soft);
      border-bottom: 1px solid var(--dw-hairline-warm);
      padding: 14px 16px 12px;
      display: flex; align-items: center; gap: 12px;
      flex-shrink: 0;
      box-shadow: 0 2px 8px rgba(0,0,0,.08);
      position: relative;
    }
    .fv-detail-name  { font-size: 15px; font-weight: 800; color: var(--dw-ink-warm-alt); line-height: 1.2; }
    .fv-detail-meta  { font-size: var(--font-xs); color: var(--dw-meta-brown); margin-top: 3px; line-height: 1.5; }
    .fv-detail-del-btn {
      width: 34px; height: 34px; border-radius: var(--radius-lg);
      background: rgba(200,60,60,.1);
      border: 1.5px solid rgba(200,60,60,.3);
      color: var(--dw-loss-red-alt2); -webkit-text-fill-color: var(--dw-loss-red-alt2);
      display: flex; align-items: center; justify-content: center;
      cursor: pointer; flex-shrink: 0;
      transition: background var(--dur-base), transform var(--dur-fast);
    }
    .fv-detail-del-btn:hover { background: rgba(200,60,60,.2); transform: scale(1.08); }
    .fv-detail-body  {
      flex: 1;
      overflow: hidden;
      padding: 0;
      display: flex;
      flex-direction: column;
    }
    .fv-detail-body::-webkit-scrollbar { width: 4px; }
    .fv-detail-body::-webkit-scrollbar-track { background: transparent; }
    .fv-detail-body::-webkit-scrollbar-thumb { background: rgba(184,144,42,.35); border-radius: var(--radius-sm); }

    /* বকেয়া / জমা বাটন */
    .fv-entry-btns {
      display: flex; gap: 10px;
      padding: 10px 8px 6px;
    }
    .fv-bokeyoa-btn, .fv-joma-btn {
      font-family: var(--fab-sans);
      flex: 1; padding: 13px 10px; border-radius: var(--radius-3xl);
      font-size: 14px; font-weight: 800; cursor: pointer; border: none;
      display: flex; align-items: center; justify-content: center; gap: 7px;
      transition: filter var(--dur-fast), transform var(--dur-2xs);
    }
    .fv-bokeyoa-btn:active, .fv-joma-btn:active { transform: scale(.97); }
    .fv-bokeyoa-btn {
      background: var(--btn-bill-bg);
      color: var(--dw-white);
      box-shadow: 0 4px 16px rgba(192,32,32,.45);
    }
    .fv-bokeyoa-btn:hover  { filter: brightness(1.10); }
    .fv-bokeyoa-btn.active { background: var(--btn-bill-active-bg); }
    .fv-joma-btn {
      background: var(--btn-joma-bg);
      color: var(--dw-white);
      box-shadow: 0 4px 16px rgba(24,146,74,.45);
    }
    .fv-joma-btn:hover  { filter: brightness(1.10); }
    .fv-joma-btn.active { background: var(--btn-joma-active-bg); }

    /* মিনি এন্ট্রি ফর্ম */
    .fv-mini-form {
      display: none;
      margin: 0 0 4px;
      background: var(--dw-cream-soft);
      border: 1.5px solid rgba(184,144,42,.35);
      border-radius: var(--radius-2xl);
      padding: 12px;
      flex-direction: column;
      gap: 8px;
      box-shadow: none;
    }
    .fv-mini-form.open { display: flex; }
    .fv-mini-form-title {
      font-size: 11px; font-weight: 800; color: var(--dw-amber-label);
      padding-bottom: 6px;
      border-bottom: 1px solid rgba(184,144,42,.35);
    }
    .fv-mini-row { display: flex; gap: 8px; align-items: center; }

    /* Floating Label — fv-mini (fieldset/legend) */
    .fv-mini-field {
      position: relative; flex: 1; min-width: 0; margin-top: 10px;
      display: flex; flex-direction: column;
    }
    .fv-mini-field fieldset {
      border: 1.5px solid var(--border);
      border-radius: var(--radius-md);
      padding: 0; margin: 0;
      background: var(--dz-canvas);
      transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
      min-width: 0;
    }
    .fv-mini-field fieldset:focus-within {
      border-color: var(--gold2);
    }
    .fv-mini-field legend {
      font-family: var(--fab-sans);
      font-size: var(--font-2xs); font-weight: 700;
      color: transparent;
      padding: 0; margin-left: 6px;
      line-height: 0;
      max-width: 0;
      white-space: nowrap;
      overflow: hidden;
      transition: max-width var(--dur-base), padding var(--dur-base);
    }
    .fv-mini-field fieldset:focus-within legend,
    .fv-mini-field.has-val legend {
      max-width: fit-content;
      padding: 0 4px;
    }
    .fv-mini-label {
      position: absolute;
      left: 8px; top: 50%; transform: translateY(-50%);
      font-size: 12px; font-weight: 600; color: var(--muted);
      pointer-events: none;
      transition: top var(--dur-base), transform var(--dur-base), font-size var(--dur-base), color var(--dur-base);
      line-height: 1;
    }
    .fv-mini-field fieldset:focus-within ~ .fv-mini-label,
    .fv-mini-field.has-val .fv-mini-label {
      top: 0; transform: translateY(-50%);
      font-size: var(--font-2xs); font-weight: 700;
      color: var(--gold);
      left: 10px;
    }
    .fv-mini-field fieldset:focus-within ~ .fv-mini-label { color: var(--gold2); }
    .fv-mini-inp {
      font-family: var(--fab-sans);
      padding: 9px 8px 8px;
      border: none; outline: none;
      font-size: 12px; color: var(--ink);
      background: transparent;
      width: 100%;
      border-radius: var(--radius-base);
      display: block;
    }
    .fv-mini-inp.amt { text-align: right; }
    .fv-mini-save-btn {
      font-family: var(--fab-sans);
      align-self: flex-end;
      padding: 6px 16px; border-radius: var(--radius-lg);
      border: 1.5px solid rgba(184,144,42,.4);
      background: var(--gold2); color: var(--ink);
      font-size: 12px; font-weight: 700; cursor: pointer;
      display: flex; align-items: center; gap: 5px;
      transition: background var(--dur-fast);
    }
    .fv-mini-save-btn:hover { background: var(--dw-save-hover); }

    .fv-excel { width: max-content; min-width: 100%; border-collapse: collapse; font-size: 11px; }
    .fv-table-card {
      margin: 0;
      border-radius: 0;
      border: none;
      box-shadow: none;
      background: transparent;
      display: flex;
      flex-direction: column;
      flex: 1;
      min-height: 0;
      overflow: hidden;
    }
    .fv-excel-wrap {
      overflow-x: scroll;
      overflow-y: auto;
      flex: 1;
      min-height: 0;
      -webkit-overflow-scrolling: touch;
      scroll-behavior: auto;
      overscroll-behavior: contain;
    }
    .fv-excel thead tr { background: var(--dw-forest-dark); }
    .fv-excel thead th {
      padding: 6px 9px; color: var(--dw-white-full) !important;
      font-size: var(--font-xs); font-weight: 800;
      text-align: center; white-space: nowrap;
      border-right: 1px solid rgba(184,144,42,.18);
      position: sticky; top: 0; z-index: var(--z-sticky);
      background: var(--dw-forest-dark);
    }
    .fv-excel thead th:last-child { border-right: none; }
    .fv-excel tbody tr { border-bottom: 1px solid rgba(160,130,80,0.18); }
    .fv-excel tbody tr:nth-child(even) { background: rgba(180,160,100,0.12); }
    .fv-excel tbody tr:last-child { border-bottom: none; }
    .fv-excel tbody tr:hover { background: rgba(180,160,100,0.22); }
    .fv-excel tbody td {
      padding: 7px 9px; text-align: center; color: var(--dw-ink-deep);
      border-right: 1px solid rgba(160,130,80,0.12); white-space: nowrap;
    }
    .fv-excel tbody td:last-child { border-right: none; }
    .fv-excel .td-label { text-align: left; font-weight: 700; }
    .fv-excel .td-baki  { color: var(--dw-loss-red); font-weight: 800; }
    .fv-excel .td-joma  { color: var(--dw-forest-green); font-weight: 700; }
    /* বিল লাইন — হালকা লাল */
    .fv-excel tbody tr.tr-bill { background: rgba(155,44,44,.07); }
    .fv-excel tbody tr.tr-bill td { color: var(--dw-red-deep); }
    .fv-excel tbody tr.tr-bill:hover { background: rgba(155,44,44,.14); }
    /* জমা লাইন — হালকা সবুজ */
    .fv-excel tbody tr.tr-joma { background: rgba(26,92,53,.06); }
    .fv-excel tbody tr.tr-joma td { color: var(--dw-forest-green); }
    .fv-excel tbody tr.tr-joma:hover { background: rgba(26,92,53,.12); }
    .fv-excel-foot {
      display: flex; justify-content: space-between; align-items: center;
      padding: 6px 12px;
      background: rgba(160,130,80,0.10);
      border-top: 1px solid rgba(160,130,80,0.22);
    }
    .fv-excel-foot-lbl { color: var(--dw-meta-brown); font-size: var(--font-xs); font-weight: 600; }
    .fv-excel-foot-val { color: var(--dw-loss-red); font-weight: 800; font-size: 13px; }
    .fv-foot-del-btn {
      width: 30px; height: 30px; border-radius: var(--radius-md);
      background: rgba(200,60,60,.1);
      border: 1.5px solid rgba(200,60,60,.35);
      color: var(--dw-loss-red-alt2); -webkit-text-fill-color: var(--dw-loss-red-alt2);
      display: flex; align-items: center; justify-content: center;
      cursor: pointer; flex-shrink: 0;
      transition: background var(--dur-base), transform var(--dur-fast);
    }
    .fv-foot-del-btn:hover { background: rgba(200,60,60,.22); transform: scale(1.08); }
    .fv-card-del-row {
      display: flex; align-items: center; justify-content: flex-end;
      gap: 8px; margin-top: 5px;
    }
    .fv-card-baki-lbl {
      font-size: 11px; font-weight: 800; color: var(--dw-loss-red);
    }

    /* লং প্রেস অ্যাকশন বার */
    .fv-lp-action-bar {
      display: none;
      align-items: center;
      justify-content: space-between;
      padding: 7px 12px 6px;
      background: rgba(200,150,30,0.13);
      border-radius: var(--radius-2xl);
      border: 1px solid rgba(200,150,30,0.30);
      margin: 0 2px 6px;
      animation: lpBarIn .18s ease;
    }
    @keyframes lpBarIn {
      from { opacity:0; transform:translateY(-6px); }
      to   { opacity:1; transform:none; }
    }
    .fv-lp-action-bar.show { display: flex; }
    .fv-lp-action-name {
      font-size: 12px; font-weight: 800;
      color: var(--dw-ink-deep);
      flex: 1; min-width: 0;
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    }
    .fv-lp-action-btns {
      display: flex; align-items: center; gap: 6px; flex-shrink: 0;
    }
    .fv-lp-edit-btn {
      font-family: var(--fab-sans);
      display: inline-flex; align-items: center; gap: 5px;
      padding: 6px 12px; border-radius: var(--radius-lg);
      border: 1.5px solid rgba(184,144,42,.45);
      background: rgba(184,144,42,.12); color: var(--dw-amber-mid); -webkit-text-fill-color: var(--dw-amber-mid);
      font-size: 12px; font-weight: 700; cursor: pointer;
      transition: background var(--dur-fast);
    }
    .fv-lp-edit-btn:hover { background: rgba(184,144,42,.25); }
    .fv-lp-del-btn {
      font-family: var(--fab-sans);
      display: inline-flex; align-items: center; gap: 5px;
      padding: 6px 12px; border-radius: var(--radius-lg);
      border: 1.5px solid rgba(200,60,60,.45);
      background: rgba(200,60,60,.10); color: var(--dw-loss-red); -webkit-text-fill-color: var(--dw-loss-red);
      font-size: 12px; font-weight: 700; cursor: pointer;
      transition: background var(--dur-fast);
    }
    .fv-lp-del-btn:hover { background: rgba(200,60,60,.22); }
    .fv-lp-cancel-btn {
      width: 28px; height: 28px; border-radius: var(--radius-md);
      border: 1px solid rgba(120,90,50,.25);
      background: rgba(120,90,50,.08); color: var(--dw-meta-brown); -webkit-text-fill-color: var(--dw-meta-brown);
      font-size: 14px; cursor: pointer;
      display: flex; align-items: center; justify-content: center;
    }
    /* লং প্রেসে কার্ড হাইলাইট */
    .fv-card.lp-selected {
      border-color: rgba(200,150,30,0.70);
      box-shadow: 0 2px 8px rgba(0,0,0,.10), 0 0 0 2px rgba(200,150,30,0.35);
    }
    /* lp-selected অবস্থায় drag handle-এ touch-action none — scroll block করো */
    .fv-card.lp-selected .fv-drag-handle {
      touch-action: none;
      -webkit-user-select: none;
    }

    /* এডিট মোড বাটন ও সেল স্টাইল
    */
    .tbl-edit-mode-btn {
      display: inline-flex; align-items: center; justify-content: center;
      width: 32px; height: 32px; padding: 0; border-radius: var(--radius-lg);
      border: 1.5px solid rgba(184,144,42,.45);
      background: rgba(184,144,42,.12);
      color: var(--dw-amber-dark); -webkit-text-fill-color: var(--dw-amber-dark);
      cursor: pointer;
      transition: background var(--dur-fast), border-color var(--dur-fast), color var(--dur-fast);
      flex-shrink: 0;
    }
    .tbl-edit-mode-btn:hover {
      background: rgba(184,144,42,.22);
      border-color: rgba(184,144,42,.7);
      color: var(--dw-brown-deepest);
    }
    .tbl-edit-mode-btn.active {
      background: var(--gradient-gold-alt);
      border-color: var(--dw-gold-border);
      color: var(--dw-bg-deepest);
      box-shadow: 0 2px 8px rgba(184,144,42,.35);
    }
    /* এডিট মোডে সেল ইনপুট */
    .fv-excel.edit-mode tbody td.editable-cell {
      padding: 2px 3px;
      cursor: text;
    }
    .fv-excel.edit-mode tbody td.editable-cell input.cell-input {
      font-family: var(--fab-sans);
      width: 100%; min-width: 60px;
      padding: 4px 6px;
      border: 1.5px solid rgba(184,144,42,.5);
      border-radius: var(--radius-2xs);
      background: rgba(255,250,235,.95);
      color: var(--dw-ink-warm-alt);
      font-size: 11px; font-weight: 600;
      outline: none;
      text-align: inherit;
    }
    .fv-excel.edit-mode tbody td.editable-cell input.cell-input:focus {
      border-color: var(--gold);
      box-shadow: 0 0 0 2px rgba(184,144,42,.18);
      background: var(--dw-white);
    }
    /* এডিট মোডে row ডিলিট বাটন */
    .row-del-btn {
      display: inline-flex; align-items: center; justify-content: center;
      width: 28px; height: 28px;
      border-radius: var(--radius-base);
      border: 1.5px solid rgba(200,60,60,.45);
      background: rgba(200,60,60,.10);
      color: var(--dw-danger-bright); -webkit-text-fill-color: var(--dw-danger-bright);
      cursor: pointer;
      transition: background var(--dur-fast), border-color var(--dur-fast);
      padding: 0;
    }
    .row-del-btn:hover {
      background: rgba(200,60,60,.22);
      border-color: rgba(200,60,60,.7);
      color: var(--dw-red-bright);
    }
    .fv-excel.edit-mode tbody td[data-field="del-btn"] {
      text-align: center;
      vertical-align: middle;
      padding: 4px 6px;
      white-space: nowrap;
    }
    /* এডিট মোডে সেভ বাটন */
    .tbl-edit-save-btn {
      font-family: var(--fab-sans);
      display: inline-flex; align-items: center; gap: 5px;
      padding: 5px 13px; border-radius: var(--radius-lg);
      border: 1.5px solid rgba(26,92,53,.5);
      background: rgba(26,92,53,.12);
      color: var(--dw-forest-green);
      font-size: 11px; font-weight: 700;
      cursor: pointer;
      transition: background var(--dur-fast);
      white-space: nowrap;
      flex-shrink: 0;
    }
    .tbl-edit-save-btn:hover {
      background: rgba(26,92,53,.22);
    }

    /* সাইড মেনু — off-white context overrides */
    .side-menu .text-engraved {
      color: var(--dw-ink-deep);
      text-shadow: 0 1px 0 rgba(255,255,255,0.60), 0 -1px 0 rgba(0,0,0,0.08);
    }
    .side-menu .side-menu-body { background: var(--dw-cream-alt); }

    /* মেনু বিভাজক */
    .menu-divider {
      height: 1px;
      margin: 2px 10px;
      background: linear-gradient(90deg,
        transparent 0%,
        rgba(184,144,42,0.25) 25%,
        rgba(184,144,42,0.40) 50%,
        rgba(184,144,42,0.25) 75%,
        transparent 100%
      );
    }

    /* THEME TOGGLE — মেনু আইটেম
    */
    .theme-toggle-wrap {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 10px 14px;
      cursor: pointer;
      gap: 10px;
      border-radius: var(--radius-2xl);
      transition: background var(--dur-base);
    }
    .theme-toggle-wrap:active { background: rgba(184,144,42,.15); }
    .theme-switch {
      position: relative; width: 44px; height: 24px; flex-shrink: 0;
    }
    .theme-switch input { opacity: 0; width: 0; height: 0; position: absolute; }
    .theme-slider {
      position: absolute; inset: 0;
      background: var(--dw-bg-brown-dark);
      border: 1.5px solid var(--dw-border-gold);
      border-radius: var(--radius-pill-alt);
      transition: background var(--dur-lg);
      cursor: pointer;
    }
    .theme-slider::before {
      content: '';
      position: absolute;
      left: 2px; top: 50%;
      transform: translateY(-50%);
      width: 18px; height: 18px;
      background: var(--gold);
      border-radius: var(--radius-circle);
      transition: transform var(--dur-lg), background var(--dur-lg);
    }
    .theme-switch input:checked + .theme-slider { background: var(--dw-toggle-cream); }
    .theme-switch input:checked + .theme-slider::before {
      transform: translateX(20px) translateY(-50%);
      background: var(--dw-toggle-gold);
    }

    /* LIGHT MODE — সম্পূর্ণ সাদা
    */

    /* ১. Body background সাদা */
    body {
      /* DESIGN.md টোকেন: cream canvas / coral primary / ink */
      --dz-primary:        #cc785c;
      --dz-primary-active: #a9583e;
      --dz-primary-soft:   #f3e3dc;
      --dz-ink:            #141413;
      --dz-body:           #3d3d3a;
      --dz-body-strong:    #252523;
      --dz-muted:          #6c6a64;
      --dz-muted-soft:     #8e8b82;
      --dz-hairline:       #e6dfd8;
      --dz-hairline-soft:  #ebe6df;
      --dz-canvas:         #faf9f5;
      --dz-surface-soft:   #f5f0e8;
      --dz-surface-card:   #efe9de;
      --dz-surface-strong: #e8e0d2;
      --dz-success:        #5db872;
      --dz-error:          #c64545;
      --dz-serif: 'Noto Serif Bengali', 'Copernicus', 'Tiempos Headline', serif;

      background-color: var(--dz-canvas) !important;
      background-image: none !important;
      color: var(--dz-ink) !important;
    }
    /* ২. Header ছাড়া বাকি সব element-এর background-image বাতিল (home-card বাদে) */
    body :not(header):not(.hdr):not(.hdr *):not(.home-card):not(.home-card::before) {
      background-image: none;
    }

    /* ৩. Wood/dark background সরানো — প্রধান container গুলো cream canvas */
    body .wood-panel-bg,
    body .side-menu,
    body .side-menu-body,
    body .fv-screen,
    body .ep-sheet,
    body .notif-panel,
    body .db-modal,
    body main,
    body .main,
    body .bottom-tab-bar {
      background-color: var(--dz-canvas) !important;
      background-image: none;
    }

    /* ৪. সব text — header-বাদে, warm ink */
    body :not(header):not(.hdr):not(.hdr *):not(.fv-excel thead):not(.fv-excel thead *) {
      color: var(--dz-ink) !important;
      -webkit-text-fill-color: unset !important;
    }
    /* Excel-স্টাইল লেজার টেবিলের হেডার — গাঢ় সবুজ ব্যাকগ্রাউন্ডে সাদা লেখা */
    body .fv-excel thead th {
      color: var(--dw-white-full);
      -webkit-text-fill-color: var(--dw-white-full);
    }
    /* home card-এর text override বাদ দাও — আলাদা নিয়মে চলবে */
    body .home-card,
    body .home-card * {
      color: inherit !important;
    }

    /* ৫. Border — hairline */
    body :not(header):not(.hdr):not(.hdr *) {
      border-color: var(--dz-hairline) !important;
    }

    /* ৬. input */
    body input,
    body select,
    body textarea {
      background-color: var(--dz-canvas) !important;
      border-color: var(--dz-hairline) !important;
      color: var(--dz-ink) !important;
      border-radius: var(--radius-lg) !important;
    }
    body input:focus,
    body select:focus,
    body textarea:focus {
      border-color: var(--dz-primary) !important;
      box-shadow: 0 0 0 3px rgba(204,120,92,0.15) !important;
      outline: none !important;
    }

    /* ৭. SVG (header বাদে) */
    body :not(.hdr) svg path,
    body :not(.hdr) svg circle,
    body :not(.hdr) svg line,
    body :not(.hdr) svg polyline,
    body :not(.hdr) svg rect {
      stroke: var(--dz-body);
    }

    /* ৮. box-shadow সংযত — flat/hairline-first, ভারী shadow বাতিল */
    body :not(header):not(.hdr):not(.hdr *) {
      box-shadow: none !important;
    }

    /* ৯. overlay backdrop */
    body .ep-overlay,
    body .notif-overlay,
    body .db-overlay {
      background: rgba(0,0,0,.25);
    }

    /* ১০. positive/negative color */
    body [class*="amt-pos"],
    body [class*="amount-pos"] { color: var(--dz-success) !important; }
    body [class*="amt-neg"],
    body [class*="amount-neg"] { color: var(--dz-error) !important; }

    /* ১১. theme toggle */
    body .theme-slider {
      background-color: var(--dw-toggle-sage);
      border-color: var(--dw-toggle-sage-border);
    }
    body .theme-slider::before {
      background-color: var(--dz-success);
    }

    /* ১২. divider */
    body .menu-divider {
      background: linear-gradient(90deg,transparent,rgba(204,120,92,.35),transparent);
    }

    /* ১৩. bottom-tab icon */
    body .bottom-tab-bar svg path,
    body .bottom-tab-bar svg circle,
    body .bottom-tab-bar svg line {
      stroke: var(--dz-muted-soft);
    }
    body .bottom-tab-bar {
      border-top: 1px solid var(--dz-hairline);
      box-shadow: 0 -2px 14px rgba(20,20,19,0.06);
    }
    body .bottom-tab-bar::before { display: none; }
    body .btab-btn {
      color: var(--dz-muted-soft);
    }
    body .btab-btn svg path,
    body .btab-btn svg circle,
    body .btab-btn svg line,
    body .btab-btn svg polyline {
      stroke: var(--dz-muted-soft);
    }
    body .btab-btn.active {
      color: var(--dz-primary);
    }
    body .btab-btn.active svg path,
    body .btab-btn.active svg circle,
    body .btab-btn.active svg line,
    body .btab-btn.active svg polyline {
      stroke: var(--dz-primary);
    }
    body .btab-btn.active::after {
      background: var(--dz-primary) !important;
      box-shadow: none !important;
    }

    /* HOME CARD — DESIGN.md feature-card স্টাইল: cream surface + hairline + subtle elevation */

    body .home-grid {
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      padding: 4px 10px 14px;
    }
    body .home-card {
      background-color: var(--dz-surface-card) !important;
      background-image: none !important;
      border: 1px solid var(--dz-hairline) !important;
      border-radius: var(--radius-3xl);
      box-shadow: 0 1px 2px rgba(20,20,19,0.04), 0 4px 10px rgba(20,20,19,0.05) !important;
      overflow: hidden;
      transform: none !important;
      transition: transform var(--dur-fast) ease, box-shadow var(--dur-fast) ease, border-color var(--dur-fast) ease;
    }
    body .home-card:active {
      transform: scale(.97) !important;
      box-shadow: 0 1px 2px rgba(20,20,19,0.05) !important;
    }
    body .home-card::before {
      background-color: transparent !important;
      background-image: none !important;
    }
    body .card-body {
      align-items: flex-start;
      justify-content: flex-start;
      text-align: left;
      padding: 14px 12px 12px;
      gap: 7px;
      min-height: 92px;
    }
    /* মেডেলিয়ন রিং বন্ধ — নরম রাউন্ডেড স্কয়ার আইকন, হালকা রিং */
    body .icon-medallion {
      width: 38px; height: 38px;
      margin: 0 0 4px !important;
    }
    body .icon-medallion::before { background: none !important; }
    body .icon-medallion .icon-inner,
    body .icon-inner {
      width: 38px; height: 38px;
      border: 1px solid rgba(20,20,19,0.05) !important;
      box-shadow: 0 1px 2px rgba(20,20,19,0.06);
      font-size: 16px;
      border-radius: var(--radius-2xl) !important;
      transition: transform var(--dur-fast) ease;
    }
    body .home-card:active .icon-inner { transform: scale(.94); }
    /* আইকন রং — coral সংযত রাখা, বাকিগুলো warm-ink-tinted ভিন্ন শেড */

    /* card title — warm ink, কোরাল শুধু featured (Aggregate) কার্ডে */
    body .home-card .card-title {
      background: none !important;
      background-image: none !important;
      -webkit-text-fill-color: var(--dz-ink) !important;
      color: var(--dz-ink) !important;
      filter: none;
      font-family: 'Noto Serif Bengali', Georgia, 'Tiempos Headline', 'EB Garamond', serif;
      font-size: 13.5px;
      font-weight: 400;
      text-align: left;
      line-height: 1.25 !important;
      margin-bottom: 0;
      white-space: normal;
      letter-spacing: -0.2px !important;
    }

    /* card subtitle/count — monospace stat feel for a professional data look */
    body .home-card .card-count {
      color: var(--dz-muted) !important;
      -webkit-text-fill-color: var(--dz-muted) !important;
      text-shadow: none;
      font-size: var(--font-xs-alt) !important;
      font-weight: 500 !important;
      font-family: 'Noto Sans Bengali', -apple-system, 'StyreneB', 'Inter', sans-serif !important;
      text-align: left;
      min-height: 0;
    }
    /* ডান-নিচ কোণায় ছোট শেভরন (>) */
    body .home-card {
      position: relative;
    }

    /* হোম ট্যাবের ৬টা কার্ড — নেভবারের আড়ালে চলে যাওয়া ঠেকাতে আরো ছোট সাইজ */
    body #homeCardsGrid.home-grid {
      gap: 8px;
    }
    body #homeCardsGrid .home-card {
      min-height: 92px;
    }
    body #homeCardsGrid .card-body {
      padding: 12px 10px 10px;
      gap: 6px;
      min-height: 74px;
    }
    body #homeCardsGrid .icon-medallion,
    body #homeCardsGrid .icon-medallion .icon-inner,
    body #homeCardsGrid .icon-inner {
      width: 28px; height: 28px !important;
      margin: 0 0 2px !important;
      font-size: 13px !important;
    }
    body #homeCardsGrid .card-title {
      font-size: 11.5px !important;
      line-height: 1.2 !important;
    }
    body #homeCardsGrid .card-count {
      font-size: var(--font-2xs-alt) !important;
    }
    body #homeCardsGrid .home-card::after {
      right: 10px; bottom: 10px;
    }
    body .home-card::after {
      content: '';
      position: absolute;
      right: 14px; bottom: 14px;
      width: 6px; height: 6px;
      border-right: 2px solid var(--dz-hairline);
      border-bottom: 2px solid var(--dz-hairline);
      transform: rotate(-45deg);
      transition: border-color var(--dur-fast) ease;
    }
    body .home-card:active::after {
      border-color: var(--dz-primary);
    }
    .kpi-strip.kpi-strip-3 .home-card.card-c5.kpi-mini-card::after {
      display: none;
    }

    /* ডাটাবেইজ সংযোগ মোডাল
    */
    .db-overlay {
      display: none; position: fixed; inset: 0;
      background: rgba(0,0,0,.72); z-index: var(--z-toast-high);
      align-items: center; justify-content: center;
    }
    .db-overlay.open { display: flex; }
    .db-modal {
      width: 92%; max-width: 360px;
      border-radius: var(--radius-4xl);
      border: 1.5px solid var(--border);
      padding: 0 0 18px;
      overflow: hidden;
    }
    .db-head {
      display: flex; align-items: center; justify-content: space-between;
      padding: 13px 16px 11px;
      border-bottom: 1px solid rgba(200,168,96,.25);
    }
    .db-title { font-size: 13px; font-weight: 800; color: var(--gold2); }
    .db-status-bar {
      margin: 14px 16px 0;
      background: rgba(0,0,0,.3);
      border: 1px solid rgba(200,168,96,.2);
      border-radius: var(--radius-2xl);
      padding: 10px 14px;
      display: flex; align-items: center; gap: 10px;
    }
    .db-dot {
      width: 9px; height: 9px; border-radius: var(--radius-circle); flex-shrink: 0;
      background: var(--status-idle); transition: background var(--dur-slow);
    }
    .db-dot.connected { background: var(--status-connected); box-shadow: 0 0 6px var(--status-connected-glow); }
    .db-dot.error     { background: var(--dw-danger-soft); box-shadow: 0 0 6px var(--status-error-glow); }
    .db-dot.syncing   { background: var(--gold2); animation: dbPulse .8s infinite alternate; }
    @keyframes dbPulse { from { opacity:.4 } to { opacity:1 } }
    .db-status-text { font-size: 11px; color: var(--gold3); line-height: 1.4; }
    .db-last-sync { font-size: var(--font-xs); color: var(--muted); margin-top: 2px; }
    .db-actions {
      margin: 14px 16px 0;
      display: flex; flex-direction: column; gap: 9px;
    }
    .db-btn {
      width: 100%; padding: 11px 14px;
      border-radius: var(--radius-xl); border: 1.5px solid rgba(200,168,96,.3);
      background: rgba(255,200,80,.06);
      color: var(--gold2); font-size: 12px; font-weight: 700;
      font-family: var(--fab-sans);
      cursor: pointer; display: flex; align-items: center; gap: 10px;
      transition: background var(--dur-base);
    }
    .db-btn:hover { background: rgba(255,200,80,.13); }
    .db-btn:disabled { opacity: .45; cursor: not-allowed; }
    .db-btn i { font-size: 14px; width: 18px; text-align: center; }
    .db-btn.danger { color: var(--dw-danger-soft); border-color: rgba(224,112,112,.3); }
    .db-info {
      margin: 12px 16px 0;
      font-size: var(--font-xs); color: var(--muted);
      line-height: 1.6; text-align: center;
    }

  
    /* FV INLINE ENTRY BUTTON + FORM
    */
    .fv-entry-btn {
      font-family: var(--fab-sans);
      display: flex; align-items: center; gap: 5px;
      padding: 7px 12px;
      border-radius: var(--radius-xl);
      border: 1.5px solid rgba(100,80,40,.30);
      background: var(--gradient-menu-tan);
      color: var(--dw-ink-deep);
      font-size: 12px; font-weight: 700;
      cursor: pointer;
      white-space: nowrap;
      box-shadow: 0 2px 6px rgba(100,70,20,.25), 0 1px 0 rgba(255,230,160,.40) inset;
      transition: background var(--dur-base), box-shadow var(--dur-base);
      flex-shrink: 0;
    }
    .fv-entry-btn:hover {
      background: var(--gradient-menu-tan-light);
      box-shadow: 0 3px 10px rgba(100,70,20,.35), 0 1px 0 rgba(255,230,160,.50) inset;
    }
    .fv-entry-btn.active {
      background: var(--gradient-menu-tan-dark);
      border-color: rgba(100,70,20,.50);
      color: var(--dw-menu-text);
    }

    /* ইনলাইন ফর্ম র‍্যাপার / এন্ট্রি ফর্ম পপআপ */
    .fv-inline-form {
      position: absolute;
      top: 0; left: 0; right: 0;
      z-index: var(--z-modal-high);
      /* উপর থেকে slide down */
      transform: translateY(-100%);
      opacity: 0;
      pointer-events: none;
      transition: transform var(--dur-lg-alt2) cubic-bezier(.3,.9,.25,1), opacity var(--dur-md) ease;
      /* কার্ড স্টাইল */
      background: var(--gradient-menu-cream);
      border-bottom: 1.5px solid rgba(184,144,42,.35);
      box-shadow: 0 8px 32px rgba(0,0,0,.45), 0 2px 8px rgba(0,0,0,.30);
      border-radius: 0 0 var(--radius-5xl) var(--radius-5xl);
      padding: 14px 14px 16px;
    }
    .fv-inline-form.visible {
      transform: translateY(0);
      opacity: 1;
      pointer-events: auto;
    }
    /* backdrop — ফর্মের নিচে অন্ধকার */
    .fv-form-backdrop {
      position: absolute;
      inset: 0;
      z-index: var(--z-modal-mid);
      background: rgba(0,0,0,0);
      pointer-events: none;
      transition: background var(--dur-lg);
    }
    .fv-form-backdrop.visible {
      background: rgba(0,0,0,.45);
      pointer-events: auto;
    }
    .fv-inline-form-inner .ep-form-box {
      background: transparent;
      padding: 0;
      border: none;
      box-shadow: none;
    }
    .fv-inline-form-inner .ep-row {
      display: flex; gap: 8px; margin-bottom: 8px;
    }
    .fv-inline-form-inner .ep-field {
      flex: 1; min-width: 0;
      position: relative; margin-top: 8px;
    }
    .fv-inline-form-inner .ep-field fieldset {
      border: 1.5px solid rgba(184,144,42,.35);
      border-radius: var(--radius-lg);
      background: var(--dw-cream-soft);
      padding: 0; margin: 0;
      transition: border-color var(--dur-fast);
    }
    .fv-inline-form-inner .ep-field fieldset:focus-within {
      border-color: var(--gold2);
      box-shadow: 0 0 0 2px rgba(200,150,30,.10);
    }
    .fv-inline-form-inner .ep-field legend {
      font-size: var(--font-xs); color: var(--gold); font-weight: 700;
      padding: 0; max-width: 0; overflow: hidden; white-space: nowrap;
      transition: max-width var(--dur-base), padding var(--dur-base);
    }
    .fv-inline-form-inner .ep-field fieldset:focus-within legend,
    .fv-inline-form-inner .ep-field.has-val legend {
      max-width: fit-content; padding: 0 4px;
    }
    .fv-inline-form-inner .ep-label {
      position: absolute; left: 9px; top: 50%; transform: translateY(-50%);
      font-size: 11.5px; font-weight: 500; color: var(--dw-meta-brown-light);
      pointer-events: none;
      transition: top var(--dur-base), transform var(--dur-base), font-size var(--dur-base), color var(--dur-base);
      line-height: 1;
    }
    .fv-inline-form-inner .ep-field fieldset:focus-within ~ .ep-label,
    .fv-inline-form-inner .ep-field.has-val .ep-label {
      top: 0; transform: translateY(-50%);
      font-size: var(--font-xs); font-weight: 700; color: var(--gold); left: 11px;
    }
    .fv-inline-form-inner .ep-inp {
      font-family: var(--fab-sans);
      padding: 9px 9px 8px;
      border: none; outline: none;
      font-size: 13px; color: var(--dw-ink-warm-alt);
      background: transparent;
      width: 100%; border-radius: var(--radius-md); display: block;
    }
    .fv-inline-form-inner .ep-inp.amt { text-align: right; }
    .fv-inline-form-inner .ep-mob-wrap {
      display: flex; align-items: center;
      border: 1.5px solid rgba(184,144,42,.35);
      border-radius: var(--radius-lg); background: var(--dw-cream-soft); overflow: hidden;
      transition: border-color var(--dur-fast);
    }
    .fv-inline-form-inner .ep-mob-wrap:focus-within { border-color: var(--gold2); }
    .fv-inline-form-inner .ep-mob-prefix {
      font-size: 12px; font-weight: 700; color: var(--dw-meta-brown-light);
      padding: 0 5px 0 9px; white-space: nowrap; flex-shrink: 0;
      position: relative; line-height: 1; align-self: stretch;
      display: flex; align-items: center;
    }
    .fv-inline-form-inner .ep-mob-prefix::after {
      content: '';
      position: absolute; right: 0; top: 50%; transform: translateY(-50%);
      width: 1px; height: 18px;
      background: linear-gradient(to bottom,
        rgba(184,144,42,.55) 0px, rgba(184,144,42,.55) 4px,
        transparent 4px, transparent 7px,
        rgba(184,144,42,.55) 7px, rgba(184,144,42,.55) 11px,
        transparent 11px, transparent 14px,
        rgba(184,144,42,.55) 14px, rgba(184,144,42,.55) 18px);
    }
    .fv-inline-form-inner .ep-mob-wrap .ep-inp {
      border: none; border-radius: 0; padding-left: 5px; box-shadow: none;
      flex: 1; background: transparent;
    }
    .fv-inline-form-inner .ep-save-btn {
      font-family: var(--fab-sans);
      padding: 9px 20px; border-radius: var(--radius-xl);
      border: 1.5px solid rgba(184,144,42,.4);
      background: var(--gold2); color: var(--ink);
      font-size: 13px; font-weight: 700; cursor: pointer;
      display: flex; align-items: center; gap: 6px;
      align-self: flex-end;
      transition: background var(--dur-fast);
      box-shadow: 0 2px 8px rgba(184,144,42,.25);
      margin-top: 4px;
    }
    .fv-inline-form-inner .ep-save-btn:hover { background: var(--dw-save-hover); }

    /* BOTTOM TAB BAR — ফ্লোটিং
    */
    .bottom-tab-bar {
      position: fixed;
      bottom: 0; left: 0; right: 0;
      z-index: var(--z-overlay);
      display: flex;
      align-items: stretch;
      height: 58px;
      background:
        var(--wood-grain-fine),
        var(--wood-grain-wide),
        var(--gradient-bg-darkest);
      border-top: 1px solid rgba(200,150,30,0.30);
      box-shadow: 0 -4px 24px rgba(0,0,0,0.60);
      /* safe area — notch phone */
      padding-bottom: env(safe-area-inset-bottom, 0px);
    }
    .bottom-tab-bar::before {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg,
        rgba(255,200,80,0.06) 0%,
        transparent 60%);
      pointer-events: none;
    }

    .btab-btn {
      font-family: var(--fab-sans);
      position: relative;
      flex: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 3px;
      padding: 7px 8px 6px;
      font-size: var(--font-xs-alt);
      font-weight: 600;
      cursor: pointer;
      border: none;
      background: transparent;
      color: rgba(180,140,50,0.55);
      letter-spacing: 0.1px;
      transition: color var(--dur-base);
      -webkit-tap-highlight-color: transparent;
      z-index: var(--z-local);
    }
    .btab-btn svg {
      width: 22px;
      height: 22px;
      transition: transform var(--dur-base), opacity var(--dur-base);
      opacity: 0.55;
    }
    .btab-btn:active { opacity: 0.7; }

    .btab-btn.active {
      color: var(--dw-gold-bright);
    }
    .btab-btn.active svg {
      opacity: 1;
      transform: translateY(-1px);
    }
    /* active — নিচে গোল্ড ডট */
    .btab-btn.active::after {
      content: '';
      position: absolute;
      bottom: 4px;
      left: 50%;
      transform: translateX(-50%);
      width: 5px; height: 5px;
      border-radius: var(--radius-circle);
      background: var(--dw-gold-bright);
      box-shadow: 0 0 6px rgba(232,184,64,0.80);
    }
    /* main-এ নিচে এক্সট্রা padding — tab bar এর জায়গা */
    .main { padding-bottom: 80px; }
    /* dl-screen body-ও padding দিতে হবে */
    .dl-body { padding-bottom: 80px; }

    /* Home page Fund Flow — global alert-banner styles */
    .alert-banner { display:none; border-radius:var(--radius-3xl); padding:11px 14px; margin-bottom:8px; position:relative; }
    .alert-banner.show { display:flex; align-items:flex-start; gap:10px; }
    .alert-banner.ab-critical { background:rgba(248,113,113,0.14); border:1px solid rgba(248,113,113,0.40); }
    .alert-banner.ab-warning  { background:rgba(251,191,36,0.14);  border:1px solid rgba(251,191,36,0.40);  }
    .alert-banner.ab-orange   { background:rgba(251,146,60,0.14);  border:1px solid rgba(251,146,60,0.40);  }
    .alert-banner.ab-info     { background:rgba(56,189,248,0.14);  border:1px solid rgba(56,189,248,0.40);  }
    .alert-banner.ab-success  { background:rgba(74,222,128,0.14);  border:1px solid rgba(74,222,128,0.40);  }
    .ab-icon  { font-size:15px; flex-shrink:0; margin-top:1px; }
    .ab-body  { flex:1; min-width:0; }
    .ab-sev-badge { display:inline-block; font-size: var(--font-2xs); font-weight:800; letter-spacing:0.1em; text-transform:uppercase; border-radius:var(--radius-sm); padding:1px 5px; margin-bottom:3px; }
    .ab-critical .ab-sev-badge { background:rgba(248,113,113,0.22); color:var(--dw-badge-critical); }
    .ab-warning  .ab-sev-badge { background:rgba(251,191,36,0.22);  color:var(--dw-badge-warning); }
    .ab-info     .ab-sev-badge { background:rgba(56,189,248,0.22);  color:var(--dw-badge-info); }
    .ab-title  { font-size:12px; font-weight:700; color:var(--dw-bg-deepest); margin-bottom:2px; }
    .ab-desc   { font-size:11px; color:var(--dw-desc-brown); margin-bottom:3px; line-height:1.5; }
    .ab-action { font-size: var(--font-xs); color:var(--dw-action-brown); line-height:1.5; }
    .ab-close  { position:absolute; top:8px; right:10px; background:none; border:none; cursor:pointer; font-size:13px; color:var(--dw-close-muted); line-height:1; padding:0; opacity:0.7; }
    .ab-close:hover { opacity:1; }

